(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("arist-birds-e",[{"st": "—", "sp": "HDR", "t": "ΟΡΝΙΘΕΣ"}, {"st": null, "sp": "ἘΥΕΛΠΊΔΗς", "t": "ὀρθὴν κελεύεις, ᾗ τὸ δένδρον φαίνεται;"}, {"st": null, "sp": "Πισθέταιρος", "t": "διαρραγείης: ἥδε δ᾽ αὖ κρώζει πάλιν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί ὦ πόνηρ᾽ ἄνω κάτω πλανύττομεν;<br>ἀπολούμεθ᾽ ἄλλως τὴν ὁδὸν προφορουμένω."}, {"st": "5", "sp": "Πισθέταιρος", "t": "τὸ δ᾽ ἐμὲ κορώνῃ πειθόμενον τὸν ἄθλιον<br>ὁδοῦ περιελθεῖν στάδια πλεῖν ἢ χίλια."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τὸ δ᾽ ἐμὲ κολοιῷ πειθόμενον τὸν δύσμορον<br>ἀποσποδῆσαι τοὺς ὄνυχας τῶν δακτύλων."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ οὐδ᾽ ὅπου γῆς ἐσμὲν οἶδ᾽ ἔγωγ᾽ ἔτι."}, {"st": "10", "sp": "Ἐυελπίδης", "t": "ἐντευθενὶ τὴν πατρίδ᾽ ἂν ἐξεύροις σύ που;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐδ᾽ ἂν μὰ Δία γ᾽ ἐντεῦθεν Ἐξηκεστίδης."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οἴμοι."}, {"st": null, "sp": "Πισθέταιρος", "t": "σὺ μὲν ὦ τᾶν τὴν ὁδὸν ταύτην ἴθι."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἦ δεινὰ νὼ δέδρακεν οὑκ τῶν ὀρνέων,<br>ὁ πινακοπώλης φιλοκράτης μελαγχολῶν,<br>ὃς τώδ᾽ ἔφασκε νῷν φράσειν τὸν Τηρέα<br>τὸν ἔποφ᾽ ὃς ὄρνις ἐγένετ᾽ ἐκ τῶν ὀρνέων:<br>κἀπέδοτο τὸν μὲν Θαρρελείδου τουτονὶ<br>κολοιὸν ὀβολοῦ, τηνδεδὶ τριωβόλου.<br>τὼ δ᾽ οὐκ ἄρ᾽ ᾔστην οὐδὲν ἄλλο πλὴν δάκνειν.<br>καὶ νῦν τί κέχηνας; ἔσθ᾽ ὅποι κατὰ τῶν πετρῶν<br>ἡμᾶς ἔτ᾽ ἔξεις. οὐ γάρ ἐστ᾽ ἐνταῦθά τις<br>ὁδός."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐδὲ μὰ Δί᾽ ἐνταῦθά γ᾽ ἀτραπὸς οὐδαμοῦ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐδ᾽ ἡ κορώνη τῆς ὁδοῦ τι λέγει πέρι;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ ταὐτὰ κρώζει μὰ Δία νῦν τε καὶ τότε."}, {"st": "25", "sp": "Ἐυελπίδης", "t": "τί δὴ λέγει περὶ τῆς ὁδοῦ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δ᾽ ἄλλο γ᾽ ἢ<br>βρύκουσ᾽ ἀπέδεσθαί φησί μου τοὺς δακτύλους;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐ δεινὸν οὖν δῆτ᾽ ἐστὶν ἡμᾶς δεομένους<br>ἐς κόρακας ἐλθεῖν καὶ παρεσκευασμένους<br>ἔπειτα μὴ ‘ξευρεῖν δύνασθαι τὴν ὁδόν;<br>ἡμεῖς γάρ, ὦνδρες οἱ παρόντες ἐν λόγῳ,<br>νόσον νοσοῦμεν τὴν ἐναντίαν Σάκᾳ:<br>ὁ μὲν γὰρ ὢν οὐκ ἀστὸς ἐσβιάζεται,<br>ἡμεῖς δὲ φυλῇ καὶ γένει τιμώμενοι,<br>ἀστοὶ μετ᾽ ἀστῶν, οὐ σοβοῦντος οὐδενὸς<br>ἀνεπτόμεσθ᾽ ἐκ τῆς πατρίδος ἀμφοῖν ποδοῖν,<br>αὐτὴν μὲν οὐ μισοῦντ᾽ ἐκείνην τὴν πόλιν<br>τὸ μὴ οὐ μεγάλην εἶναι φύσει κεὐδαίμονα<br>καὶ πᾶσι κοινὴν ἐναποτεῖσαι χρήματα.<br>οἱ μὲν γὰρ οὖν τέττιγες ἕνα μῆν᾽ ἢ δύο<br>ἐπὶ τῶν κραδῶν ᾁδουσ᾽, Ἀθηναῖοι δ᾽ ἀεὶ<br>ἐπὶ τῶν δικῶν ᾁδουσι πάντα τὸν βίον.<br>διὰ ταῦτα τόνδε τὸν βάδον βαδίζομεν,<br>κανοῦν δ᾽ ἔχοντε καὶ χύτραν καὶ μυρρίνας<br>πλανώμεθα ζητοῦντε τόπον ἀπράγμονα,<br>ὅποι καθιδρυθέντε διαγενοίμεθ᾽ ἄν.<br>ὁ δὲ στόλος νῷν ἐστι παρὰ τὸν Τηρέα<br>τὸν ἔποπα, παρ᾽ ἐκείνου πυθέσθαι δεομἐνω,<br>εἴ που τοιαύτην εἶδε πόλιν ᾗ ‘πέπτετο."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὗτος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί ἔστιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἡ κορώνη μοι πάλαι<br>ἄνω τι φράζει."}, {"st": null, "sp": "Ἐυελπίδης", "t": "χὠ κολοιὸς οὑτοσὶ<br>ἄνω κέχηνεν ὡσπερεὶ δεικνύς τί μοι,<br>κοὐκ ἔσθ᾽ ὅπως οὐκ ἔστιν ἐνταῦθ᾽ ὄρνεα.<br>εἰσόμεθα δ᾽ αὐτίκ᾽, ἢν ποιήσωμεν ψόφον."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ οἶσθ᾽ ὃ δρᾶσον; τῷ σκέλει θένε τὴν πέτραν."}, {"st": "55", "sp": "Ἐυελπίδης", "t": "σὺ δὲ τῇ κεφαλῇ γ᾽, ἵν᾽ ᾖ διπλάσιος ὁ ψόφος."}, {"st": null, "sp": "Πισθέταιρος", "t": "σὺ δ᾽ οὖν λίθῳ κόψον λαβών."}, {"st": null, "sp": "Ἐυελπίδης", "t": "πάνυ γ᾽, εἰ δοκεῖ.<br>παῖ παῖ."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί λέγεις οὗτος; τὸν ἔποπα παῖ καλεῖς;<br>οὐκ ἀντὶ τοῦ παιδός σ᾽ ἐχρῆν ἐποποῖ καλεῖν;"}, {"st": null, "sp": "N", "t": "ἐποποῖ. ποιήσεις ἔτι με κόπτειν αὖθις αὖ.<br>ἐποποῖ."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "τίνες οὗτοι; τίς ὁ βοῶν τὸν δεσπότην;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "Ἄπολλον ἀποτρόπαιε τοῦ χασμήματος."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "οἴμοι τάλας ὀρνιθοθήρα τουτωί."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὕτως τι δεινὸν οὐδὲ κάλλιον λέγειν."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "ἀπολεῖσθον."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἀλλ᾽ οὐκ ἐσμὲν ἀνθρώπω."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "τί δαί;"}, {"st": "65", "sp": "Ἐυελπίδης", "t": "Ὑποδεδιὼς ἔγωγε Λιβυκὸν ὄρνεον."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "οὐδὲν λέγεις."}, {"st": null, "sp": "Ἐυελπίδης", "t": "καὶ μὴν ἐροῦ τὰ πρὸς ποδῶν."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "ὁδὶ δὲ δὴ τίς ἐστιν ὄρνις; οὐκ ἐρεῖς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἐπικεχοδὼς ἔγωγε Φασιανικός."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἀτὰρ σὺ τί θηρίον ποτ᾽ εἶ πρὸς τῶν θεῶν;"}, {"st": "70", "sp": "Θεράπων Ἔποπος", "t": "ὄρνις ἔγωγε δοῦλος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἡττήθης τινὸς<br>ἀλεκτρυόνος;"}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "οὐκ ἀλλ᾽ ὅτε περ ὁ δεσπότης<br>ἔποψ ἐγένετο, τότε γενέσθαι μ᾽ ηὔξατο<br>ὄρνιν, ἵν᾽ ἀκόλουθον διάκονόν τ᾽ ἔχῃ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "δεῖται γὰρ ὄρνις καὶ διακόνου τινός;"}, {"st": "75", "sp": "Θεράπων Ἔποπος", "t": "οὗτός γ᾽, ἅτ᾽ οἶμαι πρότερον ἄνθρωπός ποτ᾽ ὤν,<br>τοτὲ μὲν ἐρᾷ φαγεῖν ἀφύας Φαληρικάς:<br>τρέχω ‘π᾽ ἀφύας λαβὼν ἐγὼ τὸ τρύβλιον.<br>ἔτνους δ᾽ ἐπιθυμεῖ, δεῖ τορύνης καὶ χύτρας:<br>τρέχω ‘πὶ τορύνην."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τροχίλος ὄρνις οὑτοσί.<br>οἶσθ᾽ οὖν ὃ δρᾶσον ὦ τροχίλε; τὸν δεσπότην<br>ἡμῖν κάλεσον."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "ἀλλ᾽ ἀρτίως νὴ τὸν Δία<br>εὕδει καταφαγὼν μύρτα καὶ σέρφους τινάς."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὅμως ἐπέγειρον αὐτόν."}, {"st": null, "sp": "Θεράπων Ἔποπος", "t": "οἶδα μὲν σαφῶς<br>ὅτι ἀχθέσεται, σφῷν δ᾽ αὐτὸν οὕνεκ᾽ ἐπεγερῶ."}, {"st": "85", "sp": "Πισθέταιρος", "t": "κακῶς σύ γ᾽ ἀπόλοι᾽, ὥς μ᾽ ἀπέκτεινας δέει."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οἴμοι κακοδαίμων χὠ κολοιός μοἴχεται<br>ὑπὸ τοῦ δέους."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ δειλότατον σὺ θηρίον,<br>δείσας ἀφῆκας τὸν κολοιόν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "εἰπέ μοι,<br>σὺ δὲ τὴν κορώνην οὐκ ἀφῆκας καταπεσών;"}, {"st": "90", "sp": "Πισθέταιρος", "t": "μὰ Δί᾽ οὐκ ἔγωγε."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ποῦ γάρ ἐστ᾽;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀπέπτετο."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐκ ἆρ᾽ ἀφῆκας; ὦγάθ᾽ ὡς ἀνδρεῖος εἶ."}, {"st": null, "sp": "Ἔποψ", "t": "ἄνοιγε τὴν ὕλην, ἵν᾽ ἐξέλθω ποτέ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὦ Ἡράκλεις τουτὶ τί ποτ᾽ ἐστὶ τὸ θηρίον;<br>τίς ἡ πτέρωσις; τίς ὁ τρόπος τῆς τριλοφίας;"}, {"st": "95", "sp": "Ἔποψ", "t": "τίνες εἰσί μ᾽ οἱ ζητοῦντες;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "οἱ δώδεκα θεοὶ<br>εἴξασιν ἐπιτρῖψαί σε."}, {"st": null, "sp": "Ἔποψ", "t": "μῶν με σκώπτετον<br>ὁρῶντε τὴν πτέρωσιν; ἦν γὰρ ὦ ξένοι<br>ἄνθρωπος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐ σοῦ καταγελῶμεν."}, {"st": null, "sp": "Ἔποψ", "t": "ἀλλὰ τοῦ;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "τὸ ῥάμφος ἡμῖν σου γέλοιον φαίνεται."}, {"st": "100", "sp": "Ἔποψ", "t": "τοιαῦτα μέντοι Σοφοκλέης λυμαίνεται<br>ἐν ταῖς τραγῳδίαισιν ἐμὲ τὸν Τηρέα."}, {"st": null, "sp": "Ἐυελπίδης", "t": "Τηρεὺς γὰρ εἶ σύ; πότερον ὄρνις ἢ ταὧς;"}, {"st": null, "sp": "Ἔποψ", "t": "ὄρνις ἔγωγε."}, {"st": null, "sp": "Ἐυελπίδης", "t": "κᾆτά σοι ποῦ τὰ πτερά;"}, {"st": null, "sp": "Ἔποψ", "t": "ἐξερρύηκε."}, {"st": null, "sp": "Ἐυελπίδης", "t": "πότερον ὑπὸ νόσου τινός;"}, {"st": "105", "sp": "Ἔποψ", "t": "οὔκ, ἀλλὰ τὸν χειμῶνα πάντα τὤρνεα<br>πτερορρυεῖ τε καὖθις ἕτερα φύομεν.<br>ἀλλ᾽ εἴπατόν μοι σφὼ τίν᾽ ἐστόν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "νώ; βροτώ."}, {"st": null, "sp": "Ἔποψ", "t": "ποδαπὼ τὸ γένος;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὅθεν αἱ τριήρεις αἱ καλαί."}, {"st": null, "sp": "Ἔποψ", "t": "μῶν ἡλιαστά;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "μἀλλὰ θατέρου τρόπου,<br>ἀπηλιαστά."}, {"st": null, "sp": "Ἔποψ", "t": "σπείρεται γὰρ τοῦτ᾽ ἐκεῖ<br>τὸ σπέρμ᾽;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὀλίγον ζητῶν ἂν ἐξ ἀγροῦ λάβοις."}, {"st": null, "sp": "Ἔποψ", "t": "πράγους δὲ δὴ τοῦ δεομένω δεῦρ᾽ ἤλθετον;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "σοὶ ξυγγενέσθαι βουλομένω."}, {"st": null, "sp": "Ἔποψ", "t": "τίνος πέρι;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὅτι πρῶτα μὲν ἦσθ᾽ ἄνθρωπος ὥσπερ νὼ ποτέ,<br>κἀργύριον ὠφείλησας ὥσπερ νὼ ποτέ,<br>κοὐκ ἀποδιδοὺς ἔχαιρες ὥσπερ νὼ ποτέ:<br>εἶτ᾽ αὖθις ὀρνίθων μεταλλάξας φύσιν<br>καὶ γῆν ἐπέπτου καὶ θάλατταν ἐν κύκλῳ,<br>καὶ πάνθ᾽ ὅσαπερ ἄνθρωπος ὅσα τ᾽ ὄρνις φρονεῖς:<br>ταῦτ οὖν ἱκέται νὼ πρὸς σὲ δεῦρ᾽ ἀφίγμεθα,<br>εἴ τινα πόλιν φράσειας ἡμῖν εὔερον<br>ὥσπερ σισύραν ἐγκατακλινῆναι μαλθακήν."}, {"st": null, "sp": "Ἔποψ", "t": "ἔμειτα μείζω τῶν Κραναῶν ζητεῖς πόλιν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "μείζω μὲν οὐδέν, προσφορωτέραν δὲ νῷν."}, {"st": "125", "sp": "Ἔποψ", "t": "ἀριστοκρατεῖσθαι δῆλος εἶ ζητῶν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐγώ;<br>ἥκιστα: καὶ γὰρ τὸν Σκελίου βδελύττομαι."}, {"st": null, "sp": "Ἔποψ", "t": "ποίαν τιν᾽ οὖν ἥδιστ᾽ ἂν οἰκοῖτ᾽ ἂν πόλιν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὅπου τὰ μέγιστα πράγματ᾽ εἴη τοιάδε:<br>ἐπὶ τὴν θύραν μου πρῴ τις ἐλθὼν τῶν φίλων<br>λέγοι ταδί: ‘πρὸς τοῦ Διὸς τοὐλυμπίου<br>ὅπως παρέσει μοι καὶ σὺ καὶ τὰ παιδία<br>λουσάμενα πρῴ: μέλλω γὰρ ἑστιᾶν γάμους:<br>καὶ μηδαμῶς ἄλλως ποιήσῃς: εἰ δὲ μή,<br>μή μοι τότε γ᾽ ἔλθῃς, ὅταν ἐγὼ πράττω κακῶς.’"}, {"st": "135", "sp": "Ἔποψ", "t": "νὴ Δία ταλαιπώρων γε πραγμάτων ἐρᾷς.<br>τί δαὶ σύ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "τοιούτων ἐρῶ κἀγώ."}, {"st": null, "sp": "Ἔποψ", "t": "τίνων;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὅπου ξυναντῶν μοι ταδί τις μέμψεται<br>ὥσπερ ἀδικηθεὶς παιδὸς ὡραίου πατήρ:<br>‘καλῶς γέ μου τὸν υἱὸν ὦ Στιλβωνίδη<br>εὑρὼν ἀπιόντ᾽ ἀπὸ γυμνασίου λελουμένον<br>οὐκ ἔκυσας, οὐ προσεῖπας, οὐ προσηγάγου,<br>οὐκ ὠρχιπέδισας, ὢν ἐμοὶ πατρικὸς φίλος.’"}, {"st": null, "sp": "Ἔποψ", "t": "ὦ δειλακρίων σὺ τῶν κακῶν οἵων ἐρᾷς.<br>ἀτὰρ ἔστι γ᾽ ὁποίαν λέγετον εὐδαίμων πόλις<br>παρὰ τὴν ἐρυθρὰν θάλατταν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οἴμοι μηδαμῶς<br>ἡμῖν παρὰ τὴν θάλατταν, ἵν᾽ ἀνακύψεται<br>κλητῆρ᾽ ἄγουσ᾽ ἕωθεν ἡ Σαλαμινία.<br>Ἑλληνικὴν δὲ πόλιν ἔχεις ἡμῖν φράσαι;"}, {"st": null, "sp": "Ἔποψ", "t": "τί οὐ τὸν Ἠλεῖον Λέπρεον οἰκίζετον<br>ἐλθόνθ᾽;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὁτιὴ νὴ τοὺς θεοὺς ὅσ᾽ οὐκ ἰδὼν<br>βδελύττομαι τὸν Λέπρεον ἀπὸ Μελανθίου."}, {"st": null, "sp": "Ἔποψ", "t": "ἀλλ᾽ εἰσὶν ἕτεροι τῆς Λοκρίδος Ὀπούντιοι,<br>ἵνα χρὴ κατοικεῖν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἀλλ᾽ ἔγωγ᾽ Ὀπούντιος<br>οὐκ ἂν γενοίμην ἐπὶ ταλάντῳ χρυσίου.<br>οὗτος δὲ δὴ τίς ἔσθ᾽ ὁ μετ᾽ ὀρνίθων βίος;<br>σὺ γὰρ οἶσθ᾽ ἀκριβῶς."}, {"st": null, "sp": "Ἔποψ", "t": "οὐκ ἄχαρις ἐς τὴν τριβήν:<br>οὗ πρῶτα μὲν δεῖ ζῆν ἄνευ βαλλαντίου."}, {"st": null, "sp": "Ἐυελπίδης", "t": "πολλήν γ᾽ ἀφεῖλες τοῦ βίου κιβδηλίαν."}, {"st": null, "sp": "Ἔποψ", "t": "νεμόμεσθα δ᾽ ἐν κήποις τὰ λευκὰ σήσαμα<br>καὶ μύρτα καὶ μήκωνα καὶ σισύμβρια."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὑμεῖς μὲν ἆρα ζῆτε νυμφίων βίον."}, {"st": null, "sp": "Πισθέταιρος", "t": "φεῦ φεῦ:<br>ἦ μέγ᾽ ἐνορῶ βούλευμ᾽ ἐν ὀρνίθων γένει,<br>καὶ δύναμιν ἣ γένοιτ᾽ ἄν, εἰ πίθοισθέ μοι."}, {"st": null, "sp": "Ἔποψ", "t": "τί σοι πιθώμεσθ᾽;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὅ τι πίθησθε; πρῶτα μὲν<br>μὴ περιπέτεσθε πανταχῇ κεχηνότες:<br>ὡς τοῦτ᾽ ἄτιμον τοὔργον ἐστίν. αὐτίκα<br>ἐκεῖ παρ᾽ ἡμῖν τοὺς πετομένους ἢν ἔρῃ,<br>‘τίς ὄρνις οὗτος;’ ὁ Τελέας ἐρεῖ ταδί:<br>‘ἅνθρωπος ὄρνις ἀστάθμητος πετόμενος,<br>ἀτέκμαρτος, οὐδὲν οὐδέποτ᾽ ἐν ταὐτῷ μένων.’"}, {"st": null, "sp": "Ἔποψ", "t": "νὴ τὸν Διόνυσον εὖ γε μωμᾷ ταυταγί.<br>τί ἂν οὖν ποιοῖμεν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἰκίσατε μίαν πόλιν."}, {"st": null, "sp": "Ἔποψ", "t": "ποίαν δ᾽ ἂν οἰκίσαιμεν ὄρνιθες πόλιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄληθες; ὦ σκαιότατον εἰρηκὼς ἔπος,<br>βλέψον κάτω."}, {"st": null, "sp": "Ἔποψ", "t": "καὶ δὴ βλέπω."}, {"st": null, "sp": "Πισθέταιρος", "t": "βλέπε νῦν ἄνω."}, {"st": null, "sp": "Ἔποψ", "t": "βλέπω."}, {"st": null, "sp": "Πισθέταιρος", "t": "περίαγε τὸν τράχηλον."}, {"st": null, "sp": "Ἔποψ", "t": "νὴ Δία<br>ἀπολαύσομαί τί γ᾽, εἰ διαστραφήσομαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "εἶδές τι;"}, {"st": null, "sp": "Ἔποψ", "t": "τὰς νεφέλας γε καὶ τὸν οὐρανόν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐχ οὗτος οὖν δήπου ‘στὶν ὀρνίθων πόλος;"}, {"st": "180", "sp": "Ἔποψ", "t": "πόλος; τίνα τρόπον;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὥσπερ ἂν εἴποι τις τόπος.<br>ὅτι δὲ πολεῖται τοῦτο καὶ διέρχεται<br>ἅπαντα διὰ τούτου, καλεῖται νῦν πόλος.<br>ἢν δ᾽ οἰκίσητε τοῦτο καὶ φάρξηθ᾽ ἅπαξ,<br>ἐκ τοῦ πόλου τούτου κεκλήσεται πόλις.<br>ὥστ᾽ ἄρξετ᾽ ἀνθρώπων μὲν ὥσπερ παρνόπων,<br>τοὺς δ᾽ αὖ θεοὺς ἀπολεῖτε λιμῷ Μηλίῳ."}, {"st": null, "sp": "Ἔποψ", "t": "πῶς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐν μέσῳ δήπουθεν ἀήρ ἐστι γῆς.<br>εἶθ᾽ ὥσπερ ἡμεῖς, ἢν ἰέναι βουλώμεθα<br>Πυθώδε, Βοιωτοὺς δίοδον αἰτούμεθα,<br>οὕτως, ὅταν θύσωσιν ἄνθρωποι θεοῖς,<br>ἢν μὴ φόρον φέρωσιν οἱ ὑμῖν οἱ θεοί,<br>διὰ τῆς πόλεως τῆς ἀλλοτρίας καὶ τοῦ χάους<br>τῶν μηρίων τὴν κνῖσαν οὐ διαφρήσετε."}, {"st": null, "sp": "Ἔποψ", "t": "ἰοὺ ἰού:<br>μὰ γῆν μὰ παγίδας μὰ νεφέλας μὰ δίκτυα,<br>μὴ ‘γὼ νόημα κομψότερον ἤκουσά πω:<br>ὥστ᾽ ἂν κατοικίζοιμι μετὰ σοῦ τὴν πόλιν,<br>εἰ ξυνδοκοίη τοῖσιν ἄλλοις ὀρνέοις."}, {"st": null, "sp": "Πισθέταιρος", "t": "τίς ἂν οὖν τὸ πρᾶγμ᾽ αὐτοῖς διηγήσαιτο;"}, {"st": null, "sp": "Ἔποψ", "t": "σύ.<br>ἐγὼ γὰρ αὐτοὺς βαρβάρους ὄντας πρὸ τοῦ<br>ἐδίδαξα τὴν φωνήν, ξυνὼν πολὺν χρόνον."}, {"st": null, "sp": "Πισθέταιρος", "t": "πῶς δῆτ᾽ ἂν αὐτοὺς ξυγκαλέσειας;"}, {"st": null, "sp": "Ἔποψ", "t": "ῥᾳδίως.<br>δευρὶ γὰρ ἐσβὰς αὐτίκα μάλ᾽ ἐς τὴν λόχμην,<br>ἔπειτ᾽ ἀνεγείρας τὴν ἐμὴν ἀηδόνα,<br>καλοῦμεν αὐτούς: οἱ δὲ νῷν τοῦ φθέγματος<br>ἐάνπερ ἐπακούσωσι θεύσονται δρόμῳ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ φίλτατ᾽ ὀρνίθων σὺ μή νυν ἕσταθι:<br>ἀλλ᾽ ἀντιβολῶ σ᾽ ἄγ᾽ ὡς τάχιστ᾽ ἐς τὴν λόχμην<br>ἔσβαινε κἀνέγειρε τὴν ἀηδόνα."}, {"st": null, "sp": "Ἔποψ", "t": "ἄγε σύννομέ μοι παῦσαι μὲν ὕπνου,<br>λῦσον δὲ νόμους ἱερῶν ὕμνων,<br>οὓς διὰ θείου στόματος θρηνεῖς<br>τὸν ἐμὸν καὶ σὸν πολύδακρυν Ἴτυν:<br>ἐλελιζομένης δ᾽ ἱεροῖς μέλεσιν<br>γένυος ξουθῆς<br>καθαρὰ χωρεῖ διὰ φυλλοκόμου<br>μίλακος ἠχὼ πρὸς Διὸς ἕδρας,<br>ἵν᾽ ὁ χρυσοκόμας Φοῖβος ἀκούων<br>τοῖς σοῖς ἐλέγοις ἀντιψάλλων<br>ἐλεφαντόδετον φόρμιγγα θεῶν<br>ἵστησι χορούς: διὰ δ᾽ ἀθανάτων<br>στομάτων χωρεῖ ξύμφωνος ὁμοῦ<br>θεία μακάρων ὀλολυγή.<br>(αὐλεῖ)"}, {"st": null, "sp": "Ἔποψ", "t": "ὦ Ζεῦ βασιλεῦ τοῦ φθέγματος τοὐρνιθίου:<br>οἶον κατεμελίτωσε τὴν λόχμην ὃλην."}, {"st": "225", "sp": "Ἐυελπίδης", "t": "οὗτος."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί ἔστιν; οὐ σιωπήσει;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί δαί;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὕποψ μελῳδεῖν αὖ παρασκευάζεται."}, {"st": null, "sp": "Ἔποψ", "t": "ἐποποῖ ποποποποποποποῖ,<br>ἰὼ ἰὼ ἰτὼ ἰτὼ ἰτὼ ἰτὼ,<br>ἴτω τις ὧδε τῶν ἐμῶν ὁμοπτέρων:<br>ὅσοι τ᾽ εὐσπόρους ἀγροίκων γύας<br>νέμεσθε, φῦλα μυρία κριθοτράγων<br>σπερμολόγων τε γένη<br>ταχὺ πετόμενα, μαλθακὴν ἱέντα γῆρυν:<br>ὅσα τ᾽ ἐν ἄλοκι θαμὰ<br>βῶλον ἀμφιτιττυβίζεθ᾽ ὧδε λεπτὸν<br>ἡδομένᾳ φωνᾷ:<br>τιὸ τιὸ τιὸ τιὸ τιὸ τιὸ τιὸ τιό.<br>ὅσα θ᾽ ὑμῶν κατὰ κήπους ἐπὶ κισσοῦ<br>κλάδεσι νομὸν ἔχει,<br>τά τε κατ᾽ ὄρεα τά τε κοτινοτράγα τά τε κομαροφάγα,<br>ἀνύσατε πετόμενα πρὸς ἐμὰν αὐδάν:<br>τριοτὸ τριοτὸ τοτοβρίξ:<br>οἵ θ᾽ ἑλείας παρ᾽ αὐλῶνας ὀξυστόμους<br>ἐμπίδας κάπτεθ᾽, ὅσα τ᾽ εὐδρόσους γῆς τόπους<br>ἔχετε λειμῶνά τ᾽ ἐρόεντα Μαραθῶνος, ὄρνις<br>πτερυγοποίκιλός τ᾽ ἀτταγᾶς ἀτταγᾶς.<br>ὧν τ᾽ ἐπὶ πόντιον οἶδμα θαλάσσης<br>φῦλα μετ᾽ ἀλκυόνεσσι ποτῆται,<br>δεῦρ᾽ ἴτε πευσόμενοι τὰ νεώτερα,<br>πάντα γὰρ ἐνθάδε φῦλ᾽ ἀθροΐζομεν<br>οἰωνῶν ταναοδείρων.<br>ἥκει γὰρ τις δριμὺς πρέσβυς<br>καινὸς γνώμην<br>καινῶν τ᾽ ἔργων ἐγχειρητής.<br>ἀλλ᾽ ἴτ᾽ ἐς λόγους ἅπαντα,<br>δεῦρο δεῦρο δεῦρο δεῦρο."}, {"st": "260", "sp": "Χορὸς", "t": "τοροτοροτοροτοροτίξ.<br>κικκαβαῦ κικκαβαῦ.<br>τοροτοροτοροτορολιλιλίξ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁρᾷς τιν᾽ ὄρνιν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "μὰ τὸν Ἀπόλλω ‘γὼ μὲν οὔ:<br>καίτοι κέχηνά γ᾽ ἐς τὸν οὐρανὸν βλέπων."}, {"st": "265", "sp": "Πισθέταιρος", "t": "ἄλλως ἄρ᾽ οὕποψ, ὡς ἔοικ᾽, ἐς τὴν λόχμην<br>ἐσβὰς ἐπῷζε χαραδριὸν μιμούμενος."}, {"st": null, "sp": "Ὄρνις Τις", "t": "τοροτὶξ τοροτίξ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦγάθ᾽ ἀλλ᾽ εἶς οὑτοσὶ καὶ δή τις ὄρνις ἔρχεται."}, {"st": null, "sp": "Ἐυελπίδης", "t": "νὴ Δί᾽ ὄρνις δῆτα. τίς ποτ᾽ ἐστίν; οὐ δήπου ταὧς;"}, {"st": "270", "sp": "Πισθέταιρος", "t": "οὗτος αὐτὸς νῷν φράσει: τίς ἐστιν ὄρνις οὑτοσί;"}, {"st": null, "sp": "Ἔποψ", "t": "οὗτος οὐ τῶν ἠθάδων τῶνδ᾽ ὧν ὁρᾶθ᾽ ὑμεῖς ἀεί,<br>ἀλλὰ λιμναῖος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "βαβαὶ καλός γε καὶ φοινικιοῦς."}, {"st": null, "sp": "Ἔποψ", "t": "εἰκότως γε: καὶ γὰρ ὄνομ᾽ αὐτῷ ‘στὶ φοινικόπτερος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὗτος ὦ σέ τοι."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί βωστρεῖς;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἕτερος ὄρνις οὑτοσί."}, {"st": "275", "sp": "Πισθέταιρος", "t": "νὴ Δί᾽ ἕτερος δῆτα χοὖτος ἔξεδρον χρόαν ἔχων.<br>τίς ποτ᾽ ἔσθ᾽ ὁ μουσόμαντις ἄτοπος ὄρνις ὀρειβάτης;"}, {"st": null, "sp": "Ἔποψ", "t": "ὄνομα τούτῳ Μῆδός ἐστο."}, {"st": null, "sp": "Πισθέταιρος", "t": "Μῆδος; ὦναξ Ἡράκλεις:<br>εἶτα πῶς ἄνευ καμήλου Μῆδος ὤν εἰσέπτετο;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἕτερος αὖ λόφον κατειληφώς τις ὄρνις οὑτοσί."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί τὸ τέρας τουτί ποτ᾽ ἐστίν; οὐ σὺ μόνος ἄρ᾽ ἦσθ᾽ ἔποψ,<br>ἀλλὰ χοὖτος ἕτερος;"}, {"st": null, "sp": "Ἔποψ", "t": "οὑτοσὶ μέν ἐστι Φιλοκλέους<br>ἐξ ἔποπος, ἐγὼ δὲ τούτου πάππος, ὥσπερ εἰ λέγοις<br>Ἱππόνικος Καλλίου κἀξ Ἱππονίκου Καλλίας."}, {"st": null, "sp": "Πισθέταιρος", "t": "Καλλίας ἄρ᾽ οὗτος οὕρνις ἐστίν: ὡς πτερορρυεῖ."}, {"st": "285", "sp": "Ἐυελπίδης", "t": "ἅτε γὰρ ὢν γενναῖος ὑπό τε συκοφαντῶν τίλλεται,<br>αἵ τε θήλειαι προσεκτίλλουσιν αὐτοῦ τὰ πτερά."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ Πόσειδον ἕτερος αὖ τις βαπτὸς ὄρνις οὑτοσί.<br>τίς ὀνομάξεταί ποθ᾽ οὗτος;"}, {"st": null, "sp": "Ἔποψ", "t": "οὑτοσὶ κατωφαγᾶς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔστι γὰρ κατωφαγᾶς τις ἄλλος ἢ Κλεώνυμος;"}, {"st": "290", "sp": "Ἐυελπίδης", "t": "πῶς ἂν οὖν Κλεώνυμός γ᾽ ὢν οὐκ ἀπέβαλε τὸν λόφον;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλὰ μέντοι τίς ποθ᾽ ἡ λόφωσις ἡ τῶν ὀρνέων;<br>ἦ ‘πὶ τὸν δίαυλον ἦλθον;"}, {"st": null, "sp": "Ἔποψ", "t": "ὥσπερ οἱ Κᾶρες μὲν οὖν<br>ἐπὶ λόφων οἰκοῦσιν ὦγάθ᾽ ἀσφαλείας οὔνεκα."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ Πόσειδον οὐχ ὁρᾷς ὅσον συνείλεκται κακὸν<br>ὀρνέων;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὦναξ Ἄπολλον τοῦ νέφους. ἰοὺ ἰού,<br>οὐδ᾽ ἰδεῖν ἔτ᾽ ἔσθ᾽ ὑπ᾽ αὐτῶν πετομένων τὴν εἴσοδον."}, {"st": null, "sp": "Ἔποψ", "t": "οὑτοσὶ πέρδιξ, ἐκεινοσί γε νὴ Δί᾽ ἀτταγᾶς,<br>οὑτοσὶ δὲ πηνέλοψ, ἐκεινηὶ δέ γ᾽ ἀλκυών."}, {"st": null, "sp": "Πισθέταιρος", "t": "τίς γάρ ἐσθ᾽ οὕπισθεν αὐτῆς;"}, {"st": null, "sp": "Ἔποψ", "t": "ὅστις ἐστί; κειρύλος."}, {"st": "300", "sp": "Πισθέταιρος", "t": "κειρύλος γάρ ἐστιν ὄρνις;"}, {"st": null, "sp": "Ἔποψ", "t": "οὐ γάρ ἐστι Σποργίλος;<br>χαὐτηί γε γλαῦξ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί φῄς; τίς γλαῦκ᾽ Ἀθήναζ᾽ ἤγαγεν;"}, {"st": null, "sp": "Ἔποψ", "t": "κίττα τρυγὼν κορυδὸς ἐλεᾶς ὑποθυμὶς περιστερὰ<br>νέρτος ἱέραξ φάττα κόκκυξ ἐρυθρόπους κεβλήπυρις<br>πορφυρὶς κερχνῂς κολυμβὶς ἀμπελὶς φήνη δρύοψ."}, {"st": "305", "sp": "Πισθέταιρος", "t": "ἰοὺ ἰοὺ τῶν ὀρνέων, ἰοὺ ἰοὺ τῶν κοψίχων:<br>οἶα πιππίζουσι καὶ τρέχουσι διακεκραγότες.<br>ἆρ᾽ ἀπειλοῦσίν γε νῷν; οἴμοι, κεχήνασίν γέ τοι<br>καὶ βλέπουσιν ἐς σὲ κἀμέ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τοῦτο μὲν κἀμοὶ δοκεῖ."}, {"st": "310", "sp": "Χορός", "t": "ποποποποποποποποποποῖ ποῦ μ᾽ ἄρ᾽ ὃς<br>ἐκάλεσε; τίνα τόπον ἄρα ποτὲ νέμεται;"}, {"st": null, "sp": "Ἔποψ", "t": "οὑτοσὶ πάλαι πάρειμι κοὐκ ἀποστατῶ φίλων."}, {"st": null, "sp": "Χορός", "t": "τί τί τί τί τί τί τί τί: τίνα λόγον ἄρα ποτὲ<br>πρὸς ἐμὲ φίλον ἔχων;"}, {"st": null, "sp": "Ἔποψ", "t": "κοινὸν ἀσφαλῆ δίκαιον ἡδὺν ὠφελήσιμον.<br>ἄνδρε γὰρ λεπτὼ λογιστὰ δεῦρ᾽ ἀφῖχθον ὡς ἐμέ."}, {"st": null, "sp": "Χορός", "t": "ποῦ; πᾷ; πῶς φῄς;"}, {"st": "320", "sp": "Ἔποψ", "t": "φήμ᾽ ἀπ᾽ ἀνθρώπων ἀφῖχθαι δεῦρο πρεσβύτα δύο:<br>ἥκετον δ᾽ ἔχοντε πρέμνον πράγματος πελωρίου."}, {"st": null, "sp": "Χορός", "t": "ὦ μέγιστον ἐξαμαρτὼν ἐξ ὅτου ‘τράφην ἐγώ,<br>πῶς λέγεις;"}, {"st": null, "sp": "Ἔποψ", "t": "μήπω φοβηθῇς τὸν λόγον."}, {"st": null, "sp": "Χορός", "t": "τί μ᾽ ἠργάσω;"}, {"st": null, "sp": "Ἔποψ", "t": "ἄνδρ᾽ ἐδεξάμην ἐραστὰ τῆσδε τῆς ξυνουσίας."}, {"st": "325", "sp": "Χορός", "t": "καὶ δέδρακας τοῦτο τοὔργον;"}, {"st": null, "sp": "Ἔποψ", "t": "καὶ δεδρακώς γ᾽ ἥδομαι."}, {"st": null, "sp": "Χορός", "t": "κἀστὸν ἤδη που παρ᾽ ἡμῖν;"}, {"st": null, "sp": "Ἔποψ", "t": "εἰ παρ᾽ ὑμῖν εἴμ᾽ ἐγώ."}, {"st": null, "sp": "Χορός", "t": "ἔα ἔα,<br>προδεδόμεθ᾽ ἀνόσιά τ᾽ ἐπάθομεν:<br>ὃς γὰρ φίλος ἦν ὁμότροφά θ᾽ ἡμῖν<br>ἐνέμετο πεδία παρ᾽ ἡμῖν,<br>παρέβη μὲν θεσμοὺς ἀρχαίους,<br>παρέβη δ᾽ ὅρκους ὀρνίθων:<br>ἐς δὲ δόλον ἐκάλεσε, παρέβαλέ τ᾽ ἐμὲ παρὰ<br>γένος ἀνόσιον, ὅπερ ἐξότ᾽ ἐγένετ᾽ ἐπ᾽ ἐμοὶ<br>πολέμιον ἐτράφη."}, {"st": null, "sp": "Χορός", "t": "ἀλλὰ πρὸς τοῦτον μὲν ἡμῖν ἐστιν ὕστερος λόγος:<br>τὼ δὲ πρεσβύτα δοκεῖ μοι τώδε δοῦναι τὴν δίκην<br>διαφορηθῆναί θ᾽ ὑφ᾽ ἡμῶν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὡς ἀπωλόμεσθ᾽ ἄρα."}, {"st": null, "sp": "Ἐυελπίδης", "t": "αἴτιος μέντοι σὺ νῷν εἶ τῶν κακῶν τούτων μόνος.<br>ἐπὶ τί γάρ μ᾽ ἐκεῖθεν ἦγες;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἵν᾽ ἀκολουθοίης ἐμοί."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἵνα μὲν οὖν κλάοιμι μεγάλα."}, {"st": null, "sp": "Πισθέταιρος", "t": "τοῦτο μὲν ληρεῖς ἔχων<br>κάρτα: πῶς κλαύσει γάρ, ἢν ἅπαξ γε τὠφθαλμὼ ‘κκοπῇς;"}, {"st": null, "sp": "Χορός", "t": "ἰὼ ἰώ,<br>ἔπαγ᾽ ἔπιθ᾽ ἐπίφερε πολέμιον<br>ὁρμὰν φονίαν, πτέρυγά τε παντᾷ<br>ἐπίβαλε περί τε κύκλωσαι:<br>ὡς δεῖ τώδ᾽ οἰμώζειν ἄμφω<br>καὶ δοῦναι ῥύγχει φορβάν.<br>οὔτε γὰρ ὄρος σκιερὸν οὔτε νέφος αἰθέριον<br>οὔτε πολιὸν πέλαγος ἔστιν ὅ τι δέξεται<br>τώδ᾽ ἀποφυγόντε με."}, {"st": null, "sp": "Χορός", "t": "ἀλλὰ μὴ μέλλωμεν ἤδη τώδε τίλλειν καὶ δάκνειν.<br>ποῦ ‘σθ᾽ ὁ ταξίαρχος; ἐπαγέτω τὸ δεξιὸν κέρας."}, {"st": null, "sp": "Χορός", "t": "τοῦτ᾽ ἐκεῖνο: ποῖφύγω δύστηνος;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὗτος οὐ μενεῖς;"}, {"st": "355", "sp": "Ἐυελπίδης", "t": "ἵν᾽ ὑπὸ τούτων διαφορηθῶ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "πῶς γὰρ ἂν τούτους δοκεῖς<br>ἐκφυγεῖν;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐκ οἶδ᾽ ὅπως ἄν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ἐγώ τοί σοι λέγω,<br>ὅτι μένοντε δεῖ μάχεσθαι λαμβάνειν τε τῶν χυτρῶν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί δὲ χύτρα νώ γ᾽ ὠφελήσει;"}, {"st": null, "sp": "Πισθέταιρος", "t": "γλαῦξ μὲν οὐ πρόσεισι νῷν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τοῖς δὲ γαμψώνυξι τοισδί;"}, {"st": null, "sp": "Πισθέταιρος", "t": "τὸν ὀβελίσκον ἁρπάσας<br>εἶτα κατάπηξον πρὸ σαυτοῦ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τοῖσι δ᾽ ὀφθαλμοῖσι τί;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὀξύβαφον ἐντευθενὶ προσδοῦ λαβὼν ἢ τρύβλιον."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὦ σοφώτατ᾽, εὖ γ᾽ ἀνηῦρες αὐτὸ καὶ στρατηγικῶς:<br>ὑπερακοντίζεις σύ γ᾽ ἤδη Νικίαν ταῖς μηχαναῖς."}, {"st": null, "sp": "Χορός", "t": "ἐλελελεῦ χώρει κάθες τὸ ῥύγχος: οὐ μέλλειν ἐχρῆν.<br>ἕλκε τίλλε παῖε δεῖρε, κόπτε πρώτην τὴν χύτραν."}, {"st": null, "sp": "Ἔποψ", "t": "εἰπέ μοι τί μέλλετ᾽ ὦ πάντων κάκιστα θηρίων<br>ἀπολέσαι παθόντες οὐδὲν ἄνδρε καὶ διασπάσαι<br>τῆς ἐμῆς γυναικὸς ὄντε ξυγγενεῖ καὶ φυλέτα;"}, {"st": null, "sp": "Χορός", "t": "φεισόμεσθα γάρ τι τῶνδε μᾶλλον ἡμεῖς ἢ λύκων;<br>ἢ τίνας τεισαίμεθ᾽ ἄλλους τῶνδ᾽ ἂν ἐχθίους ἔτι;"}, {"st": null, "sp": "Ἔποψ", "t": "εἰ δὲ τὴν φύσιν μὲν ἐχθροὶ τὸν δὲ νοῦν εἰσιν φίλοι,<br>καὶ διδάξοντές τι δεῦρ᾽ ἥκουσιν ὑμᾶς χρήσιμον;"}, {"st": null, "sp": "Χορός", "t": "πῶς δ᾽ ἂν οἵδ᾽ ἡμᾶς τι χρήσιμον διδάξειάν ποτε<br>ἢ φράσειαν, ὄντες ἐχθροὶ τοῖσι πάπποις τοῖς ἐμοῖς;"}, {"st": "375", "sp": "Ἔποψ", "t": "ἀλλ᾽ ἀπ᾽ ἐχθρῶν δῆτα πολλὰ μανθάνουσιν οἱ σοφοί.<br>ἡ γὰρ εὐλάβεια σῴζει πάντα. παρὰ μὲν οὖν φίλου<br>οὐ μάθοις ἂν τοῦθ᾽, ὁ δ᾽ ἐχθρὸς εὐθὺς ἐξηνάγκασεν.<br>αὐτίχ᾽ αἱ πόλεις παρ᾽ ἀνδρῶν γ᾽ ἔμαθον ἐχθρῶν κοὐ φίλων<br>ἐκπονεῖν θ᾽ ὑψηλὰ τείχη ναῦς τε κεκτῆσθαι μακράς:<br>τὸ δὲ μάθημα τοῦτο σῴζει παῖδας οἶκον χρήματα."}, {"st": null, "sp": "Χορός", "t": "ἔστι μὲν λόγων ἀκοῦσαι πρῶτον, ὡς ἡμῖν δοκεῖ,<br>χρήσιμον: μάθοι γὰρ ἄν τις κἀπὸ τῶν ἐχθρῶν σοφόν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οἵδε τῆς ὀργῆς χαλᾶν εἴξασιν. ἄναγ᾽ ἐπὶ σκέλος."}, {"st": null, "sp": "Ἔποψ", "t": "καὶ δίκαιόν γ᾽ ἐστὶ κἀμοὶ δεῖ νέμειν ὑμᾶς χάριν."}, {"st": "385", "sp": "Χορός", "t": "ἀλλὰ μὴν οὐδ᾽ ἄλλο σοί πω πρᾶγμ᾽ ἐνηντιώμεθα."}, {"st": null, "sp": "Πισθέταιρος", "t": "μᾶλλον εἰρήνην ἄγουσι νὴ Δί᾽, ὥστε τὴν χύτραν<br>τώ τε τρυβλίω καθίει:<br>καὶ τὸ δόρυ χρή, τὸν ὀβελίσκον,<br>περιπατεῖν ἔχοντας ἡμᾶς<br>τῶν ὅπλων ἐντός, παρ᾽ αὐτὴν<br>τὴν χύτραν ἄκραν ὁρῶντας<br>ἐγγύς: ὡς οὐ φευκτέον νῷν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐτεὸν ἢν δ᾽ ἄρ᾽ ἀποθάνωμεν,<br>κατορυχθησόμεσθα ποῦ γῆς;"}, {"st": "395", "sp": "Πισθέταιρος", "t": "ὁ Κεραμεικὸς δέξεται νώ.<br>δημοσίᾳ γὰρ ἵνα ταφῶμεν,<br>φήσομεν πρὸς τοὺς στρατηγοὺς<br>μαχομένω τοῖς πολεμίοισιν<br>ἀποθανεῖν ἐν Ὀρνεαῖς."}, {"st": "400", "sp": "Χορός", "t": "ἄναγ᾽ ἐς τάξιν πάλιν ἐς ταὐτόν,<br>καὶ τὸν θυμὸν κατάθου κύψας<br>παρὰ τὴν ὀργὴν ὥσπερ ὁπλίτης:<br>κἀναπυθώμεθα τούσδε τίνες ποτὲ<br>καὶ πόθεν ἔμολον<br>† ἐπὶ τίνα τ᾽ ἐπίνοιαν. †<br>ἰὼ ἔποψ σέ τοι καλῶ."}, {"st": null, "sp": "Χορός", "t": "καλεῖς δὲ τοῦ κλύειν θέλων;"}, {"st": null, "sp": "Χορός", "t": "τίνες ποθ᾽ οἵδε καὶ πόθεν;"}, {"st": null, "sp": "Ἔποψ", "t": "ξείνω σοφῆς ἀφ᾽ Ἑλλάδος."}, {"st": "410", "sp": "Χορός", "t": "τύχη δὲ ποία κομίζει<br>ποτ᾽ αὐτὼ πρὸς ὄρνιθας<br>ἐλθεῖν;"}, {"st": null, "sp": "Ἔποψ", "t": "ἔρως<br>βίου διαίτης τε καὶ<br>σοῦ ξυνοικεῖν τέ σοι<br>καὶ ξυνεῖναι τὸ πᾶν."}, {"st": null, "sp": "Χορός", "t": "τί φῄς;<br>λέγουσι δὴ τίνας λόγους;"}, {"st": null, "sp": "Ἔποψ", "t": "ἄπιστα καὶ πέρα κλύειν."}, {"st": null, "sp": "Χορός", "t": "ὁρᾷ τι κέρδος ἐνθάδ᾽ ἄξιον<br>μονῆς, ὅτῳ πέποιθ᾽<br>ἐμοὶ ξυνὼν<br>κρατεῖν ἂν ἢ τὸν ἐχθρὸν ἢ<br>φίλοισιν ὠφελεῖν ἔχειν;"}, {"st": null, "sp": "Ἔποψ", "t": "λέγει μέγαν τιν᾽ ὄλβον οὔτε<br>λεκτὸν οὔτε πιστόν: ὡς<br>σὰ γὰρ τὰ πάντα ταῦτα καὶ<br>τὸ τῇδε καὶ τὸ κεῖσε καὶ<br>τὸ δεῦρο προσβιβᾷ λέγων."}, {"st": null, "sp": "Χορός", "t": "πότερα μαινόμενος;"}, {"st": null, "sp": "Ἔποψ", "t": "ἄφατον ὡς φρόνιμος."}, {"st": null, "sp": "Χορός", "t": "ἔνι σοφόν τι φρενί;"}, {"st": "430", "sp": "Ἔποψ", "t": "πυκνότατον κίναδος,<br>σόφισμα κύρμα τρῖμμα παιπάλημ᾽ ὅλον."}, {"st": null, "sp": "Χορός", "t": "λέγειν λέγειν κέλευέ μοι.<br>κλύων γὰρ ὧν σύ μοι λέγεις<br>λόγων ἀνεπτέρωμαι."}, {"st": "435", "sp": "Ἔποψ", "t": "ἄγε δὴ σὺ καὶ σὺ τὴν πανοπλίαν μὲν πάλιν<br>ταύτην λαβόντε κρεμάσατον τύχἀγαθῇ<br>ἐς τὸν ἰπνὸν εἴσω πλησίον τοὐπιστάτου:<br>σὺ δὲ τούσδ᾽ ἐφ᾽ οἷσπερ τοῖς λόγοις συνέλεξ᾽ ἐγὼ<br>φράσον, δίδαξον."}, {"st": null, "sp": "Πισθέταιρος", "t": "μὰ τὸν Ἀπόλλω ‘γὼ μὲν οὔ,<br>ἢν μὴ διάθωνταί γ᾽ οἵδε διαθήκην ἐμοὶ<br>ἥνπερ ὁ πίθηκος τῇ γυναικὶ διέθετο,<br>ὁ μαχαιροποιός, μήτε δάκνειν τούτους ἐμὲ<br>μήτ᾽ ὀρχίπεδ᾽ ἕλκειν μήτ᾽ ὀρύττειν —"}, {"st": null, "sp": "Χορός", "t": "οὔτι που<br>τόν — ; οὐδαμῶς."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὔκ, ἀλλὰ τὠφθαλμὼ λέγω."}, {"st": null, "sp": "Χορός", "t": "διατίθεμαι ‘γώ."}, {"st": null, "sp": "Πισθέταιρος", "t": "κατόμοσόν νυν ταῦτά μοι."}, {"st": "445", "sp": "Χορός", "t": "ὄμνυμ᾽ ἐπὶ τούτοις, πᾶσι νικᾶν τοῖς κριταῖς<br>καὶ τοῖς θεαταῖς πᾶσιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔσται ταυταγί."}, {"st": null, "sp": "Χορός", "t": "εἰ δὲ παραβαίην, ἑνὶ κριτῇ νικᾶν μόνον."}, {"st": null, "sp": "Κῆρυξ", "t": "ἀκούετε λεῴ: τοὺς ὁπλίτας νυνμενὶ<br>ἀνελομένους θὤπλ᾽ ἀπιέναι πάλιν οἴκαδε,<br>σκοπεῖν δ᾽ ὅ τι ἂν προγράφωμεν ἐν τοῖς πινακίοις."}, {"st": null, "sp": "Χορός", "t": "δολερὸν μὲν ἀεὶ κατὰ πάντα δὴ τρόπον<br>πέφυκεν ἄνθρωπος: σὺ δ᾽ ὅμως λέγε μοι.<br>τάχα γὰρ τύχοις ἂν<br>χρηστὸν ἐξειπὼν ὅ τι μοι παρορᾷς, ἢ<br>δύναμίν τινα μείζω<br>παραλειπομένην ὑπ᾽ ἐμῆς φρενὸς ἀξυνέτου:<br>σὺ δὲ τοῦθ᾽ οὑρᾷς λέγ᾽ ἐς κοινόν.<br>ὃ γὰρ ἂν σὺ τύχῃς μοι<br>ἀγαθὸν πορίσας, τοῦτο κοινὸν ἔσται."}, {"st": "460", "sp": "Χορός", "t": "ἀλλ᾽ ἐφ᾽ ὅτῳπερ πράγματι τὴν σὴν ἥκεις γνώμην ἀναπείσας,<br>λέγε θαρρήσας: ὡς τὰς σπονδὰς οὐ μὴ πρότεροι παραβῶμεν."}, {"st": null, "sp": "Χορός", "t": "καὶ μὴν ὀργῶ νὴ τὸν Δία καὶ προπεφύραται λόγος εἷς μοι,<br>ὃν διαμάττειν οὐ κωλύει: φέρε παῖ στέφανον: καταχεῖσθαι<br>κατὰ χειρὸς ὕδωρ φερέτω ταχύ τις."}, {"st": null, "sp": "Ἐυελπίδης", "t": "δειπνήσειν μέλλομεν; ἢ τί;"}, {"st": "465", "sp": "Πισθέταιρος", "t": "μὰ Δί᾽ ἀλλὰ λέγειν ζητῶ τι πάλαι μέγα καὶ λαρινὸν ἔπος τι,<br>ὅ το τὴν τούτων θραύσει ψυχήν: οὕτως ὑμῶν ὑπεραλγῶ,<br>οἵτινες ὄντες πρότερον βασιλῆς —"}, {"st": null, "sp": "Χορός", "t": "ἡμεῖς βασιλῆς; τίνος;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὑμεῖς<br>πάντων ὁπόσ᾽ ἔστιν, ἐμοῦ πρῶτον, τουδί, καὶ τοῦ Διὸς αὐτοῦ,<br>ἀρχαιότεροι πρότεροί τε Κρόνου καὶ Τιτάνων ἐγένεσθε,<br>καὶ γῆς."}, {"st": null, "sp": "Χορός", "t": "καὶ γῆς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ τὸν Ἀπόλλω."}, {"st": "470", "sp": "Χορός", "t": "τουτὶ μὰ Δί᾽ οὐκ ἐπεπύσμην."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀμαθὴς γὰρ ἔφυς κοὐ πολυπράγμων, οὐδ᾽ Αἴσωπον πεπάτηκας,<br>ὃς ἔφασκε λέγων κορυδὸν πάντων πρώτην ὄρνιθα γενέσθαι,<br>προτέραν τῆς γῆς, κἄπειτα νόσῳ τὸν πατέρ᾽ αὐτῆς ἀποθνῄσκειν:<br>γῆν δ᾽ οὐκ εἶναι, τὸν δὲ προκεῖσθαι πεμπταῖον: τὴν δ᾽ ἀποροῦσαν<br>ὑπ᾽ ἀμηχανίας τὸν πατέρ᾽ αὑτῆς ἐν τῇ κεφαλῇ κατορύξαι."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὁ πατὴρ ἄρα τῆς κορυδοῦ νυνὶ κεῖται τεθνεὼς Κεφαλῆσιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὔκουν δῆτ᾽ εἰ πρότεροι μὲν γῆς πρότεροι δὲ θεῶν ἐγένοντο,<br>ὡς πρεσβυτάτων αὐτῶν ὄντῶν ὀρθῶς ἐσθ᾽ ἡ βασιλεία;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "νὴ τὸν Ἀπόλλω: πάνυ τοίνυν χρὴ ῥύγχος βόσκειν σε τὸ λοιπόν:<br>οὐκ ἀποδώσει ταχέως ὁ Ζεὺς τὸ σκῆπτρον τῷ δρυκολάπτῃ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὡς δ᾽ οὐχὶ θεοὶ τοίνυν ἦρχον τῶν ἀνθρώπων τὸ παλαιόν,<br>ἀλλ᾽ ὄρνιθες, κἀβασίλευον, πόλλ᾽ ἐστὶ τεκμήρια τούτων.<br>αὐτίκα δ᾽ ὑμῖν πρῶτ᾽ ἐπιδείξω τὸν ἀλεκτρυόν᾽, ὡς ἐτυράννει<br>ἦρχέ τε Περσῶν πρῶτον πάντων Δαρείου καὶ Μεγαβάζου,<br>ὥστε καλεῖται Περσικὸς ὄρνις ἀπὸ τῆς ἀρχῆς ἔτ᾽ ἐκείνης."}, {"st": null, "sp": "Ἐυελπίδης", "t": "διὰ ταῦτ᾽ ἄρ᾽ ἔχων καὶ νῦν ὥσπερ βασιλεὺς ὁ μέγας διαβάσκει<br>ἐπὶ τῆς κεφαλῆς τὴν κυρβασίαν τῶν ὀρνίθων μόνος ὀρθήν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὕτω δ᾽ ἴσχυσέ τε καὶ μέγας ἦν τότε καὶ πολύς, ὥστ᾽ ἔτι καὶ νῦν<br>ὑπὸ τῆς ῥώμης τῆς τότ᾽ ἐκείνης, ὁπόταν μόνον ὄρθριον ᾁσῃ,<br>ἀναπηδῶσιν πάντες ἐπ᾽ ἔργον χαλκῆς κεραμῆς σκυλοδέψαι<br>σκυτῆς βαλανῆς ἀλφιταμοιβοὶ τορνευτολυρασπιδοπηγοί:<br>οἱ δὲ βαδίζουσ᾽ ὑποδησάμενοι νύκτωρ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐμὲ τοῦτό γ᾽ ἐρώτα.<br>χλαῖναν γὰρ ἀπώλεσ᾽ ὁ μοχθηρὸς Φρυγίων ἐρίων διὰ τοῦτον.<br>ἐς δεκάτην γάρ ποτε παιδαρίου κληθεὶς ὑπέπινον ἐν ἄστει,<br>κἄρτι καθηῦδον, καὶ πρὶν δειπνεῖν τοὺς ἄλλους οὗτος ἄρ᾽ ᾖσεν:<br>κἀγὼ νομίσας ὄρθρον ἐχώρουν Ἀλιμουντάδε, κἄρτι προκύπτω<br>ἔξω τείχους καὶ λωποδύτης παίει ῥοπάλῳ με τὸ νῶτον:<br>κἀγὼ πίπτω μέλλω τε βοᾶν, ὁ δ᾽ ἀπέβλισε θοἰμάτιόν μου."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἰκτῖνος δ᾽ οὖν τῶν Ἑλλήνων ἦρχεν τότε κἀβασίλευεν."}, {"st": "500", "sp": "Χορός", "t": "τῶν Ἑλλήνων;"}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ κατέδειξέν γ᾽ οὗτος πρῶτος βασιλεύων<br>προκυλινδεῖσθαι τοῖς ἰκτίνοις."}, {"st": null, "sp": "Ἐυελπίδης", "t": "νὴ τὸν Διόνυσον, ἐγὼ γοῦν<br>ἐκυλινδούμην ἰκτῖνον ἰδών: κᾆθ᾽ ὕπτιος ὢν ἀναχάσκων<br>ὀβολὸν κατεβρόχθισα: κᾆτα κενὸν τὸν θύλακον οἴκαδ᾽ ἀφεῖλκον."}, {"st": null, "sp": "Πισθέταιρος", "t": "Αἰγύπτου δ᾽ αὖ καὶ Φοινίκης πάσης κόκκυξ βασιλεὺς ἦν:<br>χὠπόθ᾽ ὁ κόκκυξ εἴποι ‘κόκκυ,’ τότ᾽ ἂν οἱ Φοίνικες ἅπαντες<br>τοὺς πυροὺς ἂν καὶ τὰς κριθὰς ἐν τοῖς πεδίοις ἐθέριζον."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τοῦτ᾽ ἄρ᾽ ἐκεῖν᾽ ἦν τοὔπος ἀληθῶς: ‘κόκκυψωλοὶ πεδίονδε.’"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἦρχον δ᾽ οὕτω σφόδρα τὴν ἀρχήν, ὥστ᾽ εἴ τις καὶ βασιλεύοι<br>ἐν ταῖς πόλεσιν τῶν Ἑλλήνων Ἀγαμέμνων ἢ Μενέλαος,<br>ἐπὶ τῶν σκήπτρων ἐκάθητ᾽ ὄρνις μετέχων ὅ τι δωροδοκοίη."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τουτὶ τοίνυν οὐκ ᾔδη ‘γώ: καὶ δῆτά μ᾽ ἐλάμβανε θαῦμα,<br>ὁπότ᾽ ἐξέλθοι Πρίαμός τις ἔχων ὄρνιν ἐν τοῖσι τραγῳδοῖς,<br>ὁ δ᾽ ἄρ᾽ εἱστήκει τὸν Λυσικράτη τηρῶν ὅ τι δωροδοκοίη."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὃ δὲ δεινότατόν γ᾽ ἐστὶν ἁπάντων, ὁ Ζεὺς γὰρ ὁ νῦν βασιλεύων<br>αἰετὸν ὄρνιν ἕστηκεν ἔχων ἐπὶ τῆς κεφαλῆς βασιλεὺς ὤν,<br>ἡ δ᾽ αὖ θυγάτηρ γλαῦχ᾽, ὁ δ᾽ Ἀπόλλων ὥσπερ θεράπων ἱέρακα."}, {"st": null, "sp": "Ἐυελπίδης", "t": "νὴ τὴν Δήμητρ᾽ εὖ ταῦτα λέγεις. τίνος οὕνεκα ταῦτ᾽ ἄρ᾽ ἔχουσιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἵν᾽ ὅταν θύων τις ἔπειτ᾽ αὐτοῖς ἐς τὴν χεῖρ᾽, ὡς νόμος ἐστίν,<br>τὰ σπλάγχνα διδῷ, τοῦ Διὸς αὐτοὶ πρότεροι τὰ σπλάγχνα λάβωσιν.<br>ὤμνυ τ᾽ οὐδεὶς τότ᾽ ἂν ἀνθρώπων θεόν, ἀλλ᾽ ὄρνιθας ἅπαντες:<br>Λάμπων δ᾽ ὄμνυσ᾽ ἔτι καὶ νυνὶ τὸν χῆν᾽, ὅταν ἐξαπατᾷ τι.<br>οὕτως ὑμᾶς πάντες πρότερον μεγάλους ἁγίους τ᾽ ἐνόμιζον,"}, {"st": null, "sp": "Πισθέταιρος", "t": "νῦν δ᾽ ἀνδράποδ᾽ ἠλιθίους Μανᾶς:<br>ὥσπερ δ᾽ ἤδη τοὺς μαινομένους<br>βάλλουσ᾽ ὑμᾶς, κἀν τοῖς ἱεροῖς<br>πᾶς τις ἐφ᾽ ὑμῖν ὀρνιθευτὴς<br>ἵστησι βρόχους παγίδας ῥάβδους<br>ἕρκη νεφέλας δίκτυα πηκτάς:<br>εἶτα λαβόντες πωλοῦσ᾽ ἁθρόους:<br>οἱ δ᾽ ὠνοῦνται βλιμάζοντες:<br>κοὐδ᾽ οὖν, εἴπερ ταῦτα δοκεῖ δρᾶν,<br>ὀπτησάμενοι παρέθενθ᾽ ὑμᾶς,<br>ἀλλ᾽ ἐπικνῶσιν τυρὸν ἔλαιον<br>σίλφιον ὄξος καὶ τρίψαντες<br>κατάχυσμ᾽ ἕτερον γλυκὺ καὶ λιπαρόν,<br>κἄπειτα κατεσκέδασαν θερμὸν<br>τοῦτο καθ᾽ ὑμῶν<br>αὐτῶν ὥσπερ κενεβρείων."}, {"st": null, "sp": "Πισθέταιρος", "t": "πολὺ δὴ πολὺ δὴ χαλεπωτάτους λόγους<br>ἤνεγκας ἄνθρωφ᾽. ὡς ἐδάκρυσά γ᾽ ἐμῶν<br>πατέρων κάκην, οἳ<br>τάσδε τὰς τιμὰς προγόνων παραδόντων<br>ἐπ᾽ ἐμοῦ κατέλυσαν.<br>σὺ δέ μοι κατὰ δαίμονα καί τινα συντυχίαν<br>ἀγαθὴν ἥκεις ἐμοὶ σωτήρ.<br>ἀναθεὶς γὰρ ἐγώ σοι<br>τὰ νεοττία κἀμαυτὸν οἰκήσω."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ὅ τι χρὴ δρᾶν, σὺ δίδασκε παρών: ὡς ζῆν οὐκ ἄξιον ἡμῖν,<br>εἰ μὴ κομιούμεθα παντὶ τρόπῳ τὴν ἡμετέραν βασιλείαν."}, {"st": "550", "sp": "Πισθέταιρος", "t": "καὶ δὴ τοίνυν πρῶτα διδάσκω μίαν ὀρνίθων πόλιν εἶναι,<br>κἄπειτα τὸν ἀέρα πάντα κύκλῳ καὶ πᾶν τουτὶ τὸ μεταξὺ<br>περιτειχίζειν μεγάλαις πλίνθοις ὀπταῖς ὥσπερ Βαβυλῶνα."}, {"st": null, "sp": "Ἔποψ", "t": "ὦ Κεβριόνη καὶ Πορφυρίων ὡς σμερδαλέον τὸ πόλισμα."}, {"st": null, "sp": "Πισθέταιρος", "t": "κἄπειτ᾽ ἢν τοῦτ᾽ ἐπανεστήκῃ, τὴν ἀρχὴν τὸν Δί᾽ ἀπαιτεῖν:<br>κἂν μὲν μὴ φῇ μηδ᾽ ἐθελήσῃ μηδ᾽ εὐθὺς γνωσιμαχήσῃ,<br>ἱερὸν πόλεμον πρωὐδᾶν αὐτῷ, καὶ τοῖσι θεοῖσιν ἀπειπεῖν<br>διὰ τῆς χώρας τῆς ὑμετέρας ἐστυκόσι μὴ διαφοιτᾶν,<br>ὥσπερ πρότερον μοιχεύσοντες τὰς Ἀλκμήνας κατέβαινον<br>καὶ τὰς Ἀλόπας καὶ τὰς Σεμέλας: ἤνπερ δ᾽ ἐπίωσ᾽, ἐπιβάλλειν<br>σφραγῖδ᾽ αὐτοῖς ἐπὶ τὴν ψωλήν, ἵνα μὴ βινῶσ᾽ ἔτ᾽ ἐκείνας.<br>τοῖς δ᾽ ἀνθρώποις ὄρνιν ἕτερον πέμψαι κήρυκα κελεύω,<br>ὡς ὀρνίθων βασιλευόντων θύειν ὄρνισι τὸ λοιπόν,<br>κἄπειτα θεοῖς ὕστερον αὖθις: προσνείμασθαι δὲ πρεπόντως<br>τοῖσι θεοῖσιν τῶν ὀρνίθων ὃς ἂν ἁρμόττῃ καθ᾽ ἕκαστον:<br>ἢν Ἀφροδίτῃ θύῃ, πυροὺς ὄρνιθι φαληρίδι θύειν:<br>ἢν δὲ Ποσειδῶνί τις οἶν θύῃ, νήττῃ πυροὺς καθαγίζειν:<br>ἢν δ᾽ Ἡρακλέει θύῃ τι, λάρῳ ναστοὺς θύειν μελιτοῦντας:<br>κἂν Διὶ θύῃ βασιλεῖ κριόν, βασιλεύς ἐστ᾽ ὀρχίλος ὄρνις,<br>ᾧ προτέρῳ δεῖ τοῦ Διὸς αὐτοῦ σέρφον ἐνόρχην σφαγιάζειν."}, {"st": "570", "sp": "Ἐυελπίδης", "t": "ἥσθην σέρφῳ σφαγιαζομένῳ. βροντάτω νῦν ὁ μέγας Ζάν."}, {"st": null, "sp": "Χορός", "t": "καὶ πῶς ἡμᾶς νομιοῦσι θεοὺς ἄνθρωποι κοὐχὶ κολοιούς,<br>οἳ πετόμεσθα πτέρυγάς τ᾽ ἔχομεν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ληρεῖς: καὶ νὴ Δί᾽ ὅ γ᾽ Ἑρμῆς<br>πέτεται θεὸς ὢν πτέρυγάς τε φορεῖ, κἄλλοι γε θεοὶ πάνυ πολλοί.<br>αὐτίκα Νίκη πέτεται πτερύγοιν χρυσαῖν καὶ νὴ Δί᾽ Ἔρως γε:<br>Ἥρην δέ γ᾽ Ὅμηρος ἔφασκ᾽ ἰκέλην εἶναι τρήρωνι πελείῃ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὁ Ζεὺς δ᾽ ἡμῖν οὐ βροντήσας πέμψει πτερόεντα κεραυνόν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἢν δ᾽ οὖν ὑμᾶς μὲν ὑπ᾽ ἀγνοίας εἶναι νομίσωσι τὸ μηδέν,<br>τούτους δὲ θεοὺς τοὺς ἐν Ὀλύμπῳ τότε χρὴ στρούθων νέφος ἀρθὲν<br>καὶ σπερμολόγων ἐκ τῶν ἀγρῶν τὸ σπέρμ᾽ αὐτῶν ἀνακάψαι:<br>κἄπειτ᾽ αὐτοῖς ἡ Δημήτηρ πυροὺς πεινῶσι μετρείτω."}, {"st": null, "sp": "Ἐυελπίδης", "t": "οὐκ ἐθελήσει μὰ Δί᾽, ἀλλ᾽ ὄψει προφάσεις αὐτὴν παρέχουσαν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οἱ δ᾽ αὖ κόρακες τῶν ζευγαρίων, οἷσιν τὴν γῆν καταροῦσιν,<br>καὶ τῶν προβάτων τοὺς ὀφθαλμοὺς ἐκκοψάντων ἐπὶ πείρᾳ:<br>εἶθ᾽ ὅ γ᾽ Ἀπόλλων ἰατρός γ᾽ ὢν ἰάσθω: μισθοφορεῖ δέ."}, {"st": "585", "sp": "Ἐυελπίδης", "t": "μὴ πρίν γ᾽ ἂν ἐγὼ τὼ βοιδαρίω τὠμὼ πρώτιστ᾽ ἀποδῶμαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἢν δ᾽ ἡγῶνται σὲ θεὸν σὲ βίον σὲ δὲ γῆν σὲ Κρόνον σὲ Ποσειδῶ,<br>ἀγάθ᾽ αὐτοῖσιν πάντα παρέσται."}, {"st": null, "sp": "Ἔποψ", "t": "λέγε δή μοι τῶν ἀγαθῶν ἕν."}, {"st": null, "sp": "Πισθέταιρος", "t": "πρῶτα μὲν αὐτῶν τὰς οἰνάνθας οἱ πάρνοπες οὐ κατέδονται,<br>ἀλλὰ γλαυκῶν λόχος εἷς αὐτοὺς καὶ κερχνῄδων ἐπιτρίψει.<br>εἶθ᾽ οἱ κνῖπες καὶ ψῆνες ἀεὶ τὰς συκᾶς οὐ κατέδονται,<br>ἀλλ᾽ ἀναλέξει πάντας καθαρῶς αὐτοὺς ἀγέλη μία κιχλῶν."}, {"st": null, "sp": "Ἔποψ", "t": "πλουτεῖν δὲ πόθεν δώσομεν αὐτοῖς; καὶ γὰρ τούτου σφόδρ᾽ ἐρῶσιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "τὰ μέταλλ᾽ αὐτοῖς μαντευομένοις οὗτοι δώσουσι τὰ χρηστά,<br>τάς τ᾽ ἐμπορίας τὰς κερδαλέας πρὸς τὸν μάντιν κατεροῦσιν,<br>ὥστ᾽ ἀπολεῖται τῶν ναυκλήρων οὐδείς."}, {"st": null, "sp": "Ἔποψ", "t": "πῶς οὐκ ἀπολεῖται;"}, {"st": null, "sp": "Πισθέταιρος", "t": "προερεῖ τις ἀεὶ τῶν ὀρνίθων μαντευομένῳ περὶ τοῦ πλοῦ:<br>‘νυνὶ μὴ πλεῖ, χειμὼν ἔσται:’ ‘νυνὶ πλεῖ, κέρδος ἐπέσται.’"}, {"st": null, "sp": "Ἐυελπίδης", "t": "γαῦλον κτῶμαι καὶ ναυκληρῶ, κοὐκ ἂν μείναιμι παρ᾽ ὑμῖν."}, {"st": null, "sp": "Πισθέταιρος", "t": "τοὺς θησαυρούς τ᾽ αὐτοῖς δείξουσ᾽ οὓς οἱ πρότεροι κατέθεντο<br>τῶν ἀργυρίων: οὗτοι γὰρ ἴσασι: λέγουσι δέ τοι τάδε πάντες,<br>‘οὐδεὶς οἶδεν τὸν θησαυρὸν τὸν ἐμὸν πλὴν εἴ τις ἄρ᾽ ὄρνις.’"}, {"st": null, "sp": "Ἐυελπίδης", "t": "πωλῶ γαῦλον, κτῶμαι σμινύην, καὶ τὰς ὑδρίας ἀνορύττω."}, {"st": null, "sp": "Ἔποψ", "t": "πῶς δ᾽ ὑγιείαν δώσουσ᾽ αὐτοῖς, οὖσαν παρὰ τοῖσι θεοῖσιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἢν εὖ πράττωσ᾽, οὐχ ὑγιεία μεγάλη τοῦτ᾽ ἐστί; σάφ᾽ ἴσθι,<br>ὡς ἄνθρωπός γε κακῶς πράττων ἀτεχνῶς οὐδεὶς ὑγιαίνει."}, {"st": null, "sp": "Ἔποψ", "t": "πῶς δ᾽ ἐς γῆράς ποτ᾽ ἀφίξονται; καὶ γὰρ τοῦτ᾽ ἔστ᾽ ἐν Ὀλύμπῳ:<br>ἢ παιδάρι᾽ ὄντ᾽ ἀποθνῄσκειν δεῖ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "μὰ Δί᾽ ἀλλὰ τριακόσι᾽ αὐτοῖς<br>ἔτι προσθήσουσ᾽ ὄρνιθες ἔτη."}, {"st": null, "sp": "Ἔποψ", "t": "παρὰ τοῦ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "παρ᾽ ὅτου; παρ᾽ ἑαυτῶν.<br>οὐκ οἶσθ᾽ ὅτι πέντ᾽ ἀνδρῶν γενεὰς ζώει λακέρυζα κορώνη;"}, {"st": "610", "sp": "Ἐυελπίδης", "t": "αἰβοῖ πολλῷ κρείττους οὗτοι τοῦ Διὸς ἡμῖν βασιλεύειν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ γὰρ πολλῷ;<br>πρῶτον μέν γ᾽ οὐχὶ νεὼς ἡμᾶς<br>οἰκοδομεῖν δεῖ λιθίνους αὐτοῖς,<br>οὐδὲ θυρῶσαι χρυσαῖσι θύραις,<br>ἀλλ᾽ ὑπὸ θάμνοις καὶ πρινιδίοις<br>οἰκήσουσιν. τοῖς δ᾽ αὖ σεμνοῖς<br>τῶν ὀρνίθων δένδρον ἐλάας<br>ὁ νεὼς ἔσται: κοὐκ ἐς Δελφοὺς<br>οὐδ᾽ εἰς Ἄμμων᾽ ἐλθόντες ἐκεῖ<br>θύσομεν, ἀλλ᾽ ἐν ταῖσιν κομάροις<br>καὶ τοῖς κοτίνοις στάντες ἔχοντες<br>κριθὰς πυροὺς εὐξόμεθ᾽ αὐτοῖς<br>ἀνατείνοντες τὼ χεῖρ᾽ ἀγαθῶν<br>διδόναι τι μέρος: καὶ ταῦθ᾽ ἡμῖν<br>παραχρῆμ᾽ ἔσται<br>πυροὺς ὀλίγους προβαλοῦσιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ φίλτατ᾽ ἐμοὶ πολὺ πρεσβυτῶν ἐξ ἐχθίστου μεταπίπτων,<br>οὐκ ἔστιν ὅπως ἂν ἐγώ ποθ᾽ ἑκὼν τῆς σῆς γνώμης ἔτ᾽ ἀφείμην."}, {"st": null, "sp": "Χορός", "t": "ἐπαυχήσας δὲ τοῖσι σοῖς λόγοις<br>ἐπηπείλησα καὶ κατώμοσα,<br>ἢν σὺ παρ᾽ ἐμὲ θέμενος<br>ὁμόφρονας λόγους δικαίους<br>ἀδόλους ὁσίους<br>ἐπὶ θεοὺς ἴῃς, ἐμοὶ"}, {"st": "635", "sp": "Χορός", "t": "φρονῶν ξυνῳδά, μὴ πολὺν χρόνον<br>θεοὺς ἔτι σκῆπτρα τἀμὰ τρίψειν."}, {"st": null, "sp": "Χορός", "t": "ἀλλ᾽ ὅσα μὲν δεῖ ῥώμῃ πράττειν, ἐπὶ ταῦτα τεταξόμεθ᾽ ἡμεῖς:<br>ὅσα δὲ γνώμῃ δεῖ βουλεύειν, ἐπὶ σοὶ τάδε πάντ᾽ ἀνάκειται."}, {"st": null, "sp": "Ἔποψ", "t": "καὶ μὴν μὰ τὸν Δί᾽ οὐχὶ νυστάζειν ἔτι<br>ὥρα ‘στὶν ἡμῖν οὐδὲ μελλονικιᾶν,<br>ἀλλ᾽ ὡς τάχιστα δεῖ τι δρᾶν: πρῶτον δέ γε<br>εἰσέλθετ᾽ ἐς νεοττιάν γε τὴν ἐμὴν<br>καὶ τἀμὰ κάρφη καὶ τὰ παρόντα φρύγανα,<br>καὶ τοὔνομ᾽ ἡμῖν φράσατον."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλὰ ῥᾴδιον.<br>ἐμοὶ μὲν ὄνομα Πισθέταιρος, τῳδεδὶ<br>Εὐελπίδης Κριῶθεν."}, {"st": null, "sp": "Ἔποψ", "t": "ἀλλὰ χαίρετον<br>ἄμφω."}, {"st": null, "sp": "Πισθέταιρος", "t": "δεχόμεθα."}, {"st": null, "sp": "Ἔποψ", "t": "δεῦρο τοίνυν εἴσιτον."}, {"st": null, "sp": "N", "t": "ἴωμεν εἰσηγοῦ σὺ λαβὼν ἡμᾶς."}, {"st": null, "sp": "Ἔποψ", "t": "ἴθι."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀτὰρ τὸ δεῖνα, δεῦρ᾽ ἐπανάκρουσαι πάλιν.<br>φέρ᾽ ἴδω, φράσον νῷν, πῶς ἐγώ τε χοὐτοσὶ<br>ξυνεσόμεθ᾽ ὑμῖν πετομένοις οὐ πετομένω;"}, {"st": null, "sp": "Ἔποψ", "t": "καλῶς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὅρα νυν, ὡς ἐν Αἰσώπου λόγοις<br>ἐστὶν λεγόμενον δή τι, τὴν ἀλώπεχ᾽, ὡς<br>φλαύρως ἐκοινώνησεν αἰετῷ ποτέ."}, {"st": null, "sp": "Ἔποψ", "t": "μηδὲν φοβηθῇς: ἔστι γάρ τι ῥιζίον,<br>ὃ διατραγόντ᾽ ἔσεσθον ἐπτερωμένω."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὕτω μὲν εἰσίωμεν. ἄγε δὴ Ξανθία<br>καὶ Μανόδωρε λαμβάνετε τὰ στρώματα."}, {"st": null, "sp": "Χορός", "t": "οὗτος σὲ καλῶ, σὲ λέγω."}, {"st": null, "sp": "Ἔποψ", "t": "τί καλεῖς;"}, {"st": null, "sp": "Χορός", "t": "τούτους μὲν ἄγων μετὰ σαυτοῦ<br>ἀρίστισον εὖ: τὴν δ᾽ ἡδυμελῆ ξύμφωνον ἀηδόνα Μούσαις<br>κατάλειφ᾽ ἡμῖν δεῦρ᾽ ἐκβιβάσας, ἵνα παίσωμεν μετ᾽ ἐκείνης."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ τοῦτο μεντοι νὴ Δί᾽ αὐτοῖσιν πιθοῦ:<br>ἐκβίβασον ἐκ τοῦ βουτόμου τοὐρνίθιον."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐκβίβασον αὐτοῦ πρὸς θεῶν αὐτήν, ἵνα<br>καὶ νὼ θεασώμεσθα τὴν ἀηδόνα."}, {"st": "665", "sp": "Ἔποψ", "t": "ἀλλ᾽ εἰ δοκεῖ σφῷν, ταῦτα χρὴ δρᾶν. ἡ Πρόκνη<br>ἔκβαινε καὶ σαυτὴν ἐπιδείκνυ τοῖς ξένοις."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ Ζεῦ πολυτίμηθ᾽ ὡς καλὸν τοὐρνίθιον,<br>ὡς δ᾽ ἁπαλόν, ὡς δὲ λευκόν."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἆρά γ᾽ οἶσθ᾽ ὅτι<br>ἐγὼ διαμηρίζοιμ᾽ ἂν αὐτὴν ἡδέως;"}, {"st": "670", "sp": "Πισθέταιρος", "t": "ὅσον δ᾽ ἔχει τὸν χρυσόν, ὥσπερ παρθένος."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐγὼ μὲν αὐτὴν κἂν φιλῆσαί μοι δοκῶ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ὦ κακόδαιμον ῥύγχος ὀβελίσκοιν ἔχει."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἀλλ᾽ ὥσπερ ᾠὸν νὴ Δί᾽ ἀπολέψαντα χρὴ<br>ἀπὸ τῆς κεφαλῆς τὸ λέμμα κᾆθ᾽ οὕτω φιλεῖν."}, {"st": "675", "sp": "Ἔποψ", "t": "ἴωμεν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἡγοῦ δὴ σὺ νῷν τύχἀγαθῇ."}, {"st": null, "sp": "Χορός", "t": "ὦ φίλη, ὦ ξουθή,<br>ὦ φίλτατον ὀρνέων<br>πάντων, ξύννομε τῶν ἐμῶν<br>ὕμνων, ξύντροφ᾽ ἀηδοῖ,<br>ἦλθες ἦλθες ὤφθης,<br>ἡδὺν φθόγγον ἐμοὶ φέρουσ᾽.<br>ἀλλ᾽ ὦ καλλιβόαν κρέκουσ᾽<br>αὐλὸν φθέγμασιν ἠρινοῖς,<br>ἄρχου τῶν ἀναπαίστων."}, {"st": "685", "sp": "Χορός", "t": "ἄγε δὴ φύσιν ἄνδρες ἀμαυρόβιοι, φύλλων γενεᾷ προσόμοιοι,<br>ὀλιγοδρανέες, πλάσματα πηλοῦ, σκιοειδέα φῦλ᾽ ἀμενηνά,<br>ἀπτῆνες ἐφημέριοι ταλαοὶ βροτοὶ ἀνέρες εἰκελόνειροι,<br>προσέχετε τὸν νοῦν τοῖς ἀθανάτοις ἡμῖν τοῖς αἰὲν ἐοῦσιν,<br>τοῖς αἰθερίοις τοῖσιν ἀγήρῳς τοῖς ἄφθιτα μηδομένοισιν,<br>ἵν᾽ ἀκούσαντες πάντα παρ᾽ ἡμῶν ὀρθῶς περὶ τῶν μετεώρων.<br>φύσιν οἰωνῶν γένεσίν τε θεῶν ποταμῶν τ᾽ Ἐρέβους τε Χάους τε<br>εἰδότες ὀρθῶς, Προδίκῳ παρ᾽ ἐμοῦ κλάειν εἴπητε τὸ λοιπόν.<br>Χάος ἦν καὶ Νὺξ Ἔρεβός τε μέλαν πρῶτον καὶ Τάρταρος εὐρύς,<br>γῆ δ᾽ οὐδ᾽ ἀὴρ οὐδ᾽ οὐρανὸς ἦν: Ἐρέβους δ᾽ ἐν ἀπείροσι κόλποις<br>τίκτει πρώτιστον ὑπηνέμιον Νὺξ ἡ μελανόπτερος ᾠόν,<br>ἐξ οὖ περιτελλομέναις ὥραις ἔβλαστεν Ἔρως ὁ ποθεινός,<br>στίλβων νῶτον πτερύγοιν χρυσαῖν, εἰκὼς ἀνεμώκεσι δίναις.<br>οὗτος δὲ Χάει πτερόεντι μιγεὶς νυχίῳ κατὰ Τάρταρον εὐρὺν<br>ἐνεόττευσεν γένος ἡμέτερον, καὶ πρῶτον ἀνήγαγεν ἐς φῶς.<br>πρότερον δ᾽ οὐκ ἦν γένος ἀθανάτων, πρὶν Ἔρως ξυνέμειξεν ἅπαντα:<br>ξυμμιγνυμένων δ᾽ ἑτέρων ἑτέροις γένετ᾽ οὐρανὸς ὠκεανός τε<br>καὶ γῆ πάντων τε θεῶν μακάρων γένος ἄφθιτον. ὦδε μέν ἐσμεν<br>πολὺ πρεσβύτατοι πάντων μακάρων. ἡμεῖς δ᾽ ὡς ἐσμὲν Ἔρωτος<br>πολλοῖς δῆλον: πετόμεσθά τε γὰρ καὶ τοῖσιν ἐρῶσι σύνεσμεν:<br>πολλοὺς δὲ καλοὺς ἀπομωμοκότας παῖδας πρὸς τέρμασιν ὥρας<br>διὰ τὴν ἰσχὺν τὴν ἡμετέραν διεμήρισαν ἄνδρες ἐρασταί,<br>ὁ μὲν ὄρτυγα δοὺς ὁ δὲ πορφυρίων᾽ ὁ δὲ χῆν᾽ ὁ δὲ Περσικὸν ὄρνιν."}, {"st": null, "sp": "Χορός", "t": "πάντα δὲ θνητοῖς ἐστὶν ἀφ᾽ ἡμῶν τῶν ὀρνίθων τὰ μέγιστα.<br>πρῶτα μὲν ὥρας φαίνομεν ἡμεῖς ἦρος χειμῶνος ὀπώρας:<br>σπείρειν μέν, ὅταν γέρανος κρώζουσ᾽ ἐς τὴν Λιβύην μεταχωρῇ.<br>καὶ πηδάλιον τότε ναυκλήρῳ φράζει κρεμάσαντι καθεύδειν,<br>εἶτα δ᾽ Ὀρέστῃ χλαῖναν ὑφαίνειν, ἵνα μὴ ῥιγῶν ἀποδύῃ.<br>ἰκτῖνος δ᾽ αὖ μετὰ ταῦτα φανεὶς ἑτέραν ὥραν ἀποφαίνει,<br>ἡνίκα πεκτεῖν ὥρα προβάτων πόκον ἠρινόν: εἶτα χελιδών,<br>ὅτε χρὴ χλαῖναν πωλεῖν ἤδη καὶ ληδάριόν τι πρίασθαι.<br>ἐσμὲν δ᾽ ὑμῖν Ἄμμων Δελφοὶ Δωδώνη Φοῖβος Ἀπόλλων.<br>ἐλθόντες γὰρ πρῶτον ἐπ᾽ ὄρνις οὕτω πρὸς ἅπαντα τρέπεσθε,<br>πρός τ᾽ ἐμπορίαν, καὶ πρὸς βιότου κτῆσιν, καὶ πρὸς γάμον ἀνδρός.<br>ὄρνιν τε νομίζετε πάνθ᾽ ὅσαπερ περὶ μαντείας διακρίνει:<br>φήμη γ᾽ ὑμῖν ὄρνις ἐστί, πταρμόν τ᾽ ὄρνιθα καλεῖτε,<br>ξύμβολον ὄρνιν, φωνὴν ὄρνιν, θεράποντ᾽ ὄρνιν, ὄνον ὄρνιν.<br>ἆρ᾽ οὐ φανερῶς ἡμεῖς ὑμῖν ἐσμὲν μαντεῖος Ἀπόλλων;"}, {"st": null, "sp": "Χορός", "t": "ἢν οὖν ἡμᾶς νομίσητε θεούς,<br>ἕξετε χρῆσθαι μάντεσι Μούσαις<br>αὔραις ὥραις χειμῶνι θέρει<br>μετρίῳ πνίγει: κοὐκ ἀποδράντες<br>καθεδούμεθ᾽ ἄνω σεμνυνόμενοι<br>παρὰ ταῖς νεφέλαις ὥσπερ χὠ Ζεύς:<br>ἀλλὰ παρόντες δώσομεν ὑμῖν<br>αὐτοῖς, παισίν, παίδων παισίν,<br>πλουθυγιείαν<br>εὐδαιμονίαν βίον εἰρήνην<br>νεότητα γέλωτα χοροὺς θαλίας<br>γάλα τ᾽ ὀρνίθων. ὥστε παρέσται<br>κοπιᾶν ὑμῖν ὑπὸ τῶν ἀγαθῶν:<br>οὕτω πλουτήσετε πάντες."}, {"st": null, "sp": "Χορός", "t": "Μοῦσα λοχμαία,<br>τιὸ τιὸ τιὸ τιὸ τιὸ τιὸ τιοτίγξ,<br>ποικίλη, μεθ᾽ ἧς ἐγὼ<br>νάπαισι καὶ κορυφαῖς ἐν ὀρείαις,<br>τιὸ τιὸ τιὸ τιοτίγξ,<br>ἱζόμενος μελίας ἐπὶ φυλλοκόμου,<br>τιὸ τιὸ τιὸ τιοτίγξ,<br>δι᾽ ἐμῆς γένυος ξουθῆς μελέων<br>Πανὶ νόμους ἱεροὺς ἀναφαίνω<br>σεμνά τε μητρὶ χορεύματ᾽ ὀρείᾳ,<br>τοτοτοτοτοτοτοτοτοτίγξ,<br>ἔνθεν ὡστερεὶ μέλιττα<br>Φρύνιχος ἀμβροσίων μελέων ἀπεβόσκετο καρπὸν ἀεὶ<br>φέρων γλυκεῖαν ᾠδάν.<br>τιὸ τιὸ τιὸ τιοτίγξ."}, {"st": null, "sp": "Χορός", "t": "εἰ μετ᾽ ὀρνίθων τις ὑμῶν ὦ θεαταὶ βούλεται<br>διαπλέκειν ζῶν ἡδέως τὸ λοιπόν, ὡς ἡμᾶς ἴτω.<br>ὅσα γάρ ἐστιν ἐνθάδ᾽ αἰσχρὰ τῷ νόμῳ κρατούμενα,<br>ταῦτα πάντ᾽ ἐστὶν παρ᾽ ἡμῖν τοῖσιν ὄρνισιν καλά.<br>εἰ γὰρ ἐνθάδ᾽ ἐστὶν αἰσχρὸν τὸν πατέρα τύπτειν νόμῳ,<br>τοῦτ᾽ ἐκεῖ καλὸν παρ᾽ ἡμῖν ἐστιν, ἤν τις τῷ πατρὶ<br>προσδραμὼν εἴπῃ πατάξας, ‘αἶρε πλῆκτρον, εἰ μαχεῖ.’<br>εἰ δὲ τυγχάνει τις ὑμῶν δραπέτης ἐστιγμένος,<br>ἀτταγᾶς οὗτος παρ᾽ ἡμῖν ποικίλος κεκλήσεται.<br>εἰ δὲ τυγχάνει τις ὢν Φρὺξ μηδὲν ἦττον Σπινθάρου,<br>φρυγίλος ὄρνις ἐνθάδ᾽ ἔσται, τοῦ Φιλήμονος γένους.<br>εἰ δὲ δοῦλός ἐστι καὶ Κὰρ ὥσπερ Ἐξηκεστίδης,<br>φυσάτω πάππους παρ᾽ ἡμῖν, καὶ φανοῦνται φράτερες.<br>εἰ δ᾽ ὁ Πεισίου προδοῦναι τοῖς ἀτίμοις τὰς πύλας<br>βούλεται, πέρδιξ γενέσθω, τοῦ πατρὸς νεοττίον:<br>ὡς παρ᾽ ἡμῖν οὐδὲν αἰσχρόν ἐστιν ἐκπερδικίσαι."}, {"st": null, "sp": "Χορός", "t": "τοιάδε κύκνοι,<br>τιὸ τιὸ τιὰ τιὸ τιὸ τιοτίγξ,<br>συμμιγῆ βοὴν ὁμοῦ<br>πτεροῖς κρέκοντες ἴακχον Ἀπόλλω,<br>τιὸ τιὸ τιὸ τιοτίγξ,<br>ὄχθῳ ἐφεζόμενοι παρ᾽ Ἕβρον ποταμόν,<br>τιὸ τιὸ τιὸ τιοτίγξ,<br>διὰ δ᾽ αἰθέριον νέφος ἦλθε βοά:<br>πτῆξε δὲ φῦλά τε ποικίλα θηρῶν,<br>κύματά τ᾽ ἔσβεσε νήνεμος αἴθρη,<br>τοτοτοτοτοτοτοτοτοτίγξ:<br>πᾶς δ᾽ ἐπεκτύπησ᾽ Ὄλυμπος:<br>εἷλε δὲ θάμβος ἄνακτας: Ὀλυμπιάδες δὲ μέλος Χάριτες<br>Μοῦσαί τ᾽ ἐπωλόλυξαν.<br>τιὸ τιὸ τιὸ τιοτίγξ."}, {"st": "785", "sp": "Χορός", "t": "οὐδέν ἐστ᾽ ἄμεινον οὐδ᾽ ἥδιον ἢ φῦσαι πτερά.<br>αὐτίχ᾽ ὑμῶν τῶν θεατῶν εἴ τις ἧν ὑπόπτερος,<br>εἶτα πεινῶν τοῖς χοροῖσι τῶν τραγῳδῶν ἤχθετο,<br>ἐκπτόμενος ἂν οὗτος ἠρίστησεν ἐλθὼν οἴκαδε,<br>κᾆτ᾽ ἂν ἐμπλησθεὶς ἐφ᾽ ἡμᾶς αὖθις αὖ κατέπτετο.<br>εἴ τε Πατροκλείδης τις ὑμῶν τυγχάνει χεζητιῶν,<br>οὐκ ἂν ἐξίδισεν ἐς θοἰμάτιον, ἀλλ᾽ ἀνέπτετο,<br>κἀποπαρδὼν κἀναπνεύσας αὖθις αὖ κατέπτετο:<br>εἴ τε μοιχεύων τις ὑμῶν ἐστιν ὅστις τυγχάνει,<br>κᾆθ᾽ ὁρᾷ τὸν ἄνδρα τῆς γυναικὸς ἐν βουλευτικῷ,<br>οὗτος ἂν πάλιν παρ᾽ ὑμῶν πτερυγίσας ἀνέπτετο,<br>εἶτα βινήσας ἐκεῖθεν αὖθις αὖ κατέπτετο.<br>ἆρ᾽ ὑπόπτερον γενέσθαι παντός ἐστιν ἄξιον;<br>ὡς Διειτρέφης γε πυτιναῖα μόνον ἔχων πτερὰ<br>ᾑρέθη φύλαρχος, εἶθ᾽ ἵππαρχος, εἶτ᾽ ἐξ οὐδενὸς<br>μεγάλα πράττει κἀστὶ νυνὶ ξουθὸς ἱππαλεκτρυών."}, {"st": null, "sp": "Χορός", "t": "ταυτὶ τοιαυτί: μὰ Δί᾽ ἐγὼ μὲν πρᾶγμά πω<br>γελοιότερον οὐκ εἶδον οὐδεπώποτε."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἐπὶ τῷ γελᾷς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐπὶ τοῖσι σοῖς ὠκυπτέροις.<br>οἶσθ᾽ ᾧ μάλιστ᾽ ἔοικας ἐπτερωμένος;<br>εἰς εὐτέλειαν χηνὶ συγγεγραμμένῳ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "σὺ δὲ κοψίχῳ γε σκάφιον ἀποτετιλμένῳ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ταυτὶ μὲν ᾐκάσμεσθα κατὰ τὸν Αἰσχύλον:<br>τάδ᾽ οὐχ ὑπ᾽ ἄλλων ἀλλὰ τοῖς αὑτῶν πτεροῖς."}, {"st": null, "sp": "Ἔποψ", "t": "ἄγε δὴ τί χρὴ δρᾶν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "πρῶτον ὄνομα τῇ πόλει<br>θέσθαι τι μέγα καὶ κλεινόν, εἶτα τοῖς θεοῖς<br>θῦσαι μετὰ τοῦτο."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ταῦτα κἀμοὶ συνδοκεῖ."}, {"st": null, "sp": "Ἔποψ", "t": "φέρ᾽ ἴδω, τί δ᾽ ἡμῖν τοὔνομ᾽ ἔσται τῇ πόλει;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "βούλεσθε τὸ μέγα τοῦτο τοὐκ Λακεδαίμονος<br>Σπάρτην ὄνομα καλῶμεν αὐτήν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἡράκλεις:<br>Σπάρτην γὰρ ἂν θείμην ἐγὼ τἠμῇ πόλει;<br>οὐδ᾽ ἂν χαμεύνῃ πάνυ γε κειρίαν γ᾽ ἔχων."}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί δῆτ᾽ ὄνομ᾽ αὐτῇ θησόμεσθ᾽;"}, {"st": null, "sp": "Ἔποψ", "t": "ἐντευθενὶ<br>ἐκ τῶν νεφελῶν καὶ τῶν μετεώρων χωρίων<br>χαῦνόν τι πάνυ."}, {"st": null, "sp": "Πισθέταιρος", "t": "βούλει Νεφελοκοκκυγίαν;"}, {"st": null, "sp": "Ἔποψ", "t": "ἰοὺ ἰού:<br>καλόν γ᾽ ἀτεχνῶς σὺ καὶ μέγ᾽ ηὗρες τοὔνομα."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ἆρ᾽ ἐστὶν αὑτηγὶ Νεφελοκοκκυγία,<br>ἵνα καὶ τὰ Θεογένους τὰ πολλὰ χρήματα<br>τά τ᾽ Αἰσχίνου γ᾽ ἅπαντα;"}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ λῷστον μὲν οὖν<br>τὸ Φλέγρας πεδίον, ἵν᾽ οἱ θεοὶ τοὺς γηγενεῖς<br>ἀλαζονευόμενοι καθυπερηκόντισαν."}, {"st": null, "sp": "Ἔποψ", "t": "λιπαρὸν τὸ χρῆμα τῆς πόλεως. τίς δαὶ θεὸς<br>πολιοῦχος ἔσται; τῷ ξανοῦμεν τὸν πέπλον;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "τί δ᾽ οὐκ Ἀθηναίαν ἐῶμεν Πολιάδα;"}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ πῶς ἂν ἔτι γένοιτ᾽ ἂν εὔτακτος πόλις,<br>ὅπου θεὸς γυνὴ γεγονυῖα πανοπλίαν<br>ἕστηκ᾽ ἔχουσα, Κλεισθένης δὲ κερκίδα;"}, {"st": null, "sp": "Ἐυελπίδης", "t": "τίς δαὶ καθέξει τῆς πόλεως τὸ Πελαργικόν;"}, {"st": null, "sp": "Ἔποψ", "t": "ὄρνις ἀφ᾽ ἡμῶν τοῦ γένους τοῦ Περσικοῦ,<br>ὅσπερ λέγεται δεινότατος εἶναι πανταχοῦ<br>Ἄρεως νεοττός."}, {"st": null, "sp": "Ἐυελπίδης", "t": "ὦ νεοττὲ δέσποτα:<br>ὡς δ᾽ ὁ θεὸς ἐπιτήδειος οἰκεῖν ἐπὶ πετρῶν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄγε νυν σὺ μὲν βάδιζε πρὸς τὸν ἀέρα<br>καὶ τοῖσι τειχίζουσι παραδιακόνει,<br>χάλικας παραφόρει, πηλὸν ἀποδὺς ὄργασον,<br>λεκάνην ἀνένεγκε, κατάπεσ᾽ ἀπὸ τῆς κλίμακος,<br>φύλακας κατάστησαι, τὸ πῦρ ἔγκρυπτ᾽ ἀεί,<br>κωδωνοφορῶν περίτρεχε καὶ κάθευδ᾽ ἐκεῖ:<br>κήρυκα δὲ πέμψον τὸν μὲν ἐς θεοὺς ἄνω,<br>ἕτερον δ᾽ ἄνωθεν ἆυ παρ᾽ ἀνθρώπους κάτω,<br>κἀκεῖθεν αὖθις παρ᾽ ἐμέ."}, {"st": null, "sp": "Ἐυελπίδης", "t": "σὺ δέ γ᾽ αὐτοῦ μένων<br>οἴμωζε παρ᾽ ἔμ᾽."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἴθ᾽ ὦγάθ᾽ οἷ πέμπω σ᾽ ἐγώ.<br>οὐδὲν γὰρ ἄνευ σοῦ τῶνδ᾽ ἃ λέγω πεπράξεται.<br>ἐγὼ δ᾽ ἵνα θύσω τοῖσι καινοῖσιν θεοῖς,<br>τὸν ἱερέα πέμψοντα τὴν πομπὴν καλῶ.<br>παῖ παῖ, τὸ κανοῦν αἴρεσθε καὶ τὴν χέρνιβα."}, {"st": null, "sp": "Ἱερεύς", "t": "ὁμορροθῶ, συνθέλω,<br>συμπαραινέσας ἔχω<br>προσόδια μεγάλα σεμνὰ προσιέναι θεοῖσιν,<br>ἅμα δὲ προσέτι χάριτος ἕνεκα προβάτιόν τι θύειν.<br>ἴτω ἴτω δὲ Πυθιὰς βοὰ θεῷ,<br>συνᾳδέτω δὲ Χαῖρις ᾠδάν."}, {"st": null, "sp": "Ἱερεύς", "t": "παῦσαι σὺ φυσῶν. Ἡράκλεις τουτὶ τί ἦν;<br>τουτὶ μὰ Δί᾽ ἐγὼ πολλὰ δὴ καὶ δείν᾽ ἰδὼν<br>οὔπω κόρακ᾽ εἶδον ἐμπεφορβειωμένον.<br>ἱερεῦ σὸν ἔργον, θῦε τοῖς καινοῖς θεοῖς."}, {"st": null, "sp": "Ἱερεύς", "t": "δράσω τάδ᾽. ἀλλὰ ποῦ ‘στιν ὁ τὸ κανοῦν ἔχων;<br>εὔχεσθε τῇ Ἑστίᾳ τῇ ὀρνιθείῳ καὶ τῷ ἰκτίνῳ τῷ ἑστιούχῳ καὶ ὄρνισιν Ὀλυμπίοις καὶ Ὀλυμπίῃσι πᾶσι καὶ πάσῃσιν —"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ Σουνιέρακε χαῖρ᾽ ἄναξ Πελαργικέ."}, {"st": null, "sp": "Ἱερεύς", "t": "καὶ κύκνῳ Πυθίῳ καὶ Δηλίῳ καὶ Λητοῖ Ὀρτυγομήτρᾳ καὶ Ἀρτέμιδι Ἀκαλανθίδι —"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκέτι Κολαινὶς ἀλλ᾽ Ἀκαλανθὶς Ἄρτεμις."}, {"st": null, "sp": "Ἱερεύς", "t": "καὶ φρυγίλῳ Σαβαζίῳ καὶ στρούθῳ μεγάλῃ μητρὶ θεῶν καὶ ἀνθρώπων —"}, {"st": null, "sp": "Πισθέταιρος", "t": "δέσποινα Κυβέλη, στροῦθε, μῆτερ Κλεοκρίτου."}, {"st": null, "sp": "Ἱερεύς", "t": "διδόναι Νεφελοκοκκυγιεῦσιν ὑγιείαν καὶ σωτηρίαν αὐτοῖσι καὶ Χίοισι —"}, {"st": "880", "sp": "Πισθέταιρος", "t": "Χίοισιν ἥσθην πανταχοῦ προσκειμένοις."}, {"st": null, "sp": "Ἱερεύς", "t": "καὶ ἥρωσιν ὄρνισι καὶ ἡρώων παισί, πορφυρίωνι καὶ πελεκᾶντι καὶ πελεκίνῳ καὶ φλέξιδι καὶ τέτρακι καὶ ταὧνι καὶ ἐλεᾷ καὶ βασκᾷ καὶ ἐλασᾷ καὶ ἐρωδιῷ καὶ καταρράκτῃ καὶ μελαγκορύφῳ καὶ αἰγιθάλλῳ —"}, {"st": null, "sp": "Πισθέταιρος", "t": "παῦ᾽ ἐς κόρακας, παῦσαι καλῶν. ἰοὺ ἰού,<br>ἐπὶ ποῖον ὦ κακόδαιμον ἱερεῖον καλεῖς<br>ἁλιαιέτους καὶ γῦπας; οὐχ ὁρᾷς ὅτι<br>ἰκτῖνος εἷς ἂν τοῦτό γ᾽ οἴχοιθ᾽ ἁρπάσας;<br>ἄπελθ᾽ ἀφ᾽ ἡμῶν καὶ σὺ καὶ τὰ στέμματα:<br>ἐγὼ γὰρ αὐτὸς τουτογὶ θύσω μόνος."}, {"st": null, "sp": "Ἱερεύς", "t": "εἶτ᾽ αὖθις αὖ τἄρα σοι<br>δεῖ με δεύτερον μέλος<br>χέρνιβι θεοσεβὲς ὅσιον ἐπιβοᾶν, καλεῖν δὲ<br>μάκαρας, ἕνα τινὰ μόνον, εἴπερ ἱκανὸν ἕξετ᾽ ὄψον.<br>τὰ γὰρ παρόντα θύματ᾽ οὐδὲν ἄλλο πλὴν<br>γένειόν ἐστι καὶ κέρατα."}, {"st": null, "sp": "Ἱερεύς", "t": "θύοντες εὐξώμεσθα τοῖς πτερίνοις θεοῖς."}, {"st": "905", "sp": "Νεφελοκοκκυγίαν τὰν εὐδαίμονα", "t": "Νεφελοκοκκυγίαν τὰν εὐδαίμονα<br>κλῇσον ὦ Μοῦσα τεαῖς ἐν ὓμνων ἀοιδαῖς."}, {"st": null, "sp": "Πισθέταιρος", "t": "τουτὶ τὸ πρᾶγμα ποδαπόν; εἰπέ μοι τίς εἶ;"}, {"st": null, "sp": "Ποιητής", "t": "ἐγὼ μελιγλώσσων ἐπέων ἱεὶς ἀοιδὰν<br>Μουσάων θεράπων ὀτρηρός,<br>κατὰ τὸν Ὅμηρον."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔπειτα δῆτα δοῦλος ὢν κόμην ἔχεις;"}, {"st": null, "sp": "Ποιητής", "t": "οὔκ, ἀλλὰ πάντες ἐσμὲν οἱ διδάσκαλοι<br>Μουσάων θεράποντες ὀτρηροί,<br>κατὰ τὸν Ὅμηρον."}, {"st": "915", "sp": "Πισθέταιρος", "t": "οὐκ ἐτὸς ὀτρηρὸν καὶ τὸ ληδάριον ἔχεις.<br>ἀτὰρ ὦ ποιητὰ κατὰ τί δεῦρ᾽ ἀνεφθάρης;"}, {"st": null, "sp": "Ποιητής", "t": "μέλη πεποίηκ᾽ ἐς τὰς Νεφελοκοκκυγίας<br>τὰς ὑμετέρας κύκλιά τε πολλὰ καὶ καλὰ<br>καὶ παρθένεια καὶ κατὰ τὰ Σιμωνίδου."}, {"st": "920", "sp": "Πισθέταιρος", "t": "ταυτὶ σὺ πότ᾽ ἐποίησας; ἀπὸ ποίου χρόνου;"}, {"st": null, "sp": "Ποιητής", "t": "πάλαι πάλαι δὴ τήνδ᾽ ἐγὼ κλῄζω πόλιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἄρτι θύω τὴν δεκάτην ταύτης ἐγώ,<br>καὶ τοὔνομ᾽ ὥσπερ παιδίῳ νῦν δὴ ‘θέμην;"}, {"st": null, "sp": "Ποιητής", "t": "ἀλλά τις ὠκεῖα Μουσάων φάτις<br>οἷάπερ ἵππων ἀμαρυγά.<br>σὺ δὲ πάτερ κτίστορ Αἴτνας,<br>ζαθέων ἱερῶν ὁμώνυμε,<br>δὸς ἐμὶν ὅ τι περ<br>τεᾷ κεφαλᾷ θέλῃς<br>πρόφρων δόμεν ἐμὶν τείν."}, {"st": null, "sp": "Πισθέταιρος", "t": "τουτὶ παρέξει τὸ κακὸν ἡμῖν πράγματα,<br>εἰ μή τι τούτῳ δόντες ἀποφευξούμεθα.<br>οὗτος, σὺ μέντοι σπολάδα καὶ χιτῶν᾽ ἔχεις,<br>ἀπόδυθι καὶ δὸς τῷ ποιητῇ τῷ σοφῷ.<br>ἔχε τὴν σπολάδα: πάντως δέ μοι ῥιγῶν δοκεῖς."}, {"st": null, "sp": "Ποιητής", "t": "τόδε μὲν οὐκ ἀέκουσα φίλα<br>Μοῦσα δῶρον δέχεται:<br>τὺ δὲ τεᾷ φρενὶ μάθε Πινδάρειον ἔπος —"}, {"st": "940", "sp": "Πισθέταιρος", "t": "ἅνθρωπος ἡμῶν οὐκ ἀπαλλαχθήσεται."}, {"st": null, "sp": "N", "t": "νομάδεσσι γὰρ ἐν Σκύθαις ἀλᾶται Στράτων,<br>ὃς ὑφαντοδόνατον ἔσθος οὐ πέπαται:<br>ἀκλεὴς δ᾽ ἔβα σπολὰς ἄνευ χιτῶνος.<br>ξύνες ὅ τοι λέγω."}, {"st": null, "sp": "Πισθέταιρος", "t": "ξυνῆχ᾽ ὅτι βούλει τὸν χιτωνίσκον λαβεῖν.<br>ἀπόδυθι: δεῖ γὰρ τὸν ποιητὴν ὠφελεῖν.<br>ἄπελθε τουτονὶ λαβών."}, {"st": null, "sp": "Ποιητής", "t": "ἀπέρχομαι,<br>κἀς τὴν πόλιν γ᾽ ἐλθὼν ποιήσω τοιαδί:<br>‘κλῇσον ὦ χρυσόθρονε τὰν τρομερὰν κρυεράν:<br>νιφόβολα πεδία πολύπορά τ᾽ ἤλυθον ἀλαλάν.’"}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ τὸν Δί᾽ ἀλλ᾽ ἤδη πέφευγας ταυταγὶ<br>τὰ κρυερὰ τονδὶ τὸν χιτωνίσκον λαβών.<br>τουτὶ μὰ Δί᾽ ἐγὼ τὸ κακὸν οὐδέποτ᾽ ἤλπισα,<br>οὕτω ταχέως τοῦτον πεπύσθαι τὴν πόλιν.<br>αὖθις σὺ περιχώρει λαβὼν τὴν χέρνιβα.<br>εὐφημία ‘στω."}, {"st": null, "sp": "Χρησμολόγος", "t": "μὴ κατάρξῃ τοῦ τράγου."}, {"st": "960", "sp": "Πισθέταιρος", "t": "σὺ δ᾽ εἶ τίς;"}, {"st": null, "sp": "Χρησμολόγος", "t": "ὅστις; χρησμολόγος."}, {"st": null, "sp": "Πισθέταιρος", "t": "οἴμωζέ νυν."}, {"st": null, "sp": "Χρησμολόγος", "t": "ὦ δαιμόνιε τὰ θεῖα μὴ φαύλως φέρε:<br>ὡς ἔστι Βάκιδος χρησμὸς ἄντικρυς λέγων<br>ἐς τὰς Νεφελοκοκκυγίας."}, {"st": null, "sp": "Πισθέταιρος", "t": "κὔπειτα πῶς<br>ταῦτ᾽ οὐκ ἐχρησμολόγεις σὺ πρὶν ἐμὲ τὴν πόλιν<br>τήνδ᾽ οἰκίσαι;"}, {"st": null, "sp": "Χρησμολόγος", "t": "τὸ θεῖον ἐνεπόδιζέ με."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ οὐδὲν οἷόν ἐστ᾽ ἀκοῦσαι τῶν ἐπῶν."}, {"st": null, "sp": "Χρησμολόγος", "t": "ἀλλ᾽ ὅταν οἰκήσωσι λύκοι πολιαί τε κορῶναι<br>ἐν ταὐτῷ τὸ μεταξὺ Κορίνθου καὶ Σικυῶνος, —"}, {"st": null, "sp": "Πισθέταιρος", "t": "τί οὖν προσήκει δῆτ᾽ ἐμοὶ Κορινθίων;"}, {"st": "970", "sp": "Χρησμολόγος", "t": "ᾐνίξαθ᾽ ὁ Βάκις τοῦτο πρὸς τὸν ἀέρα.<br>πρῶτον Πανδώρᾳ θῦσαι λευκότριχα κριόν:<br>ὃς δέ κ᾽ ἐμῶν ἐπέων ἔλθῃ πρώτιστα προφήτης,<br>τῷ δόμεν ἱμάτιον καθαρὸν καὶ καινὰ πέδιλα —"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔνεστι καὶ τὰ πέδιλα;"}, {"st": null, "sp": "Χρησμολόγος", "t": "λαβὲ τὸ βιβλίον.<br>καὶ φιάλην δοῦναι, καὶ σπλάγχνων χεῖρ᾽ ἐπιπλῆσαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ σπλάγχνα διδόν᾽ ἔνεστι;"}, {"st": null, "sp": "Χρησμολόγος", "t": "λαβὲ τὸ βιβλίον.<br>κἂν μὲν θέσπιε κοῦρε ποιῇς ταῦθ᾽ ὡς ἐπιτέλλω,<br>αἰετὸς ἐν νεφέλῃσι γενήσεαι: αι᾽ δέ κε μὴ δῷς,<br>οὐκ ἔσει οὐ τρυγὼν οὐδ᾽ αἰετὸς οὐ δρυκολάπτης."}, {"st": "980", "sp": "Πισθέταιρος", "t": "καὶ ταῦτ᾽ ἔνεστ᾽ ἐνταῦθα;"}, {"st": null, "sp": "Χρησμολόγος", "t": "λαβὲ τὸ βιβλίον."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐδὲν ἄρ᾽ ὅμοιός ἐσθ᾽ ὁ χρησμὸς τουτῳί,<br>ὃν ἐγὼ παρὰ τἀπόλλωνος ἐξεγραψάμην:<br>αὐτὰρ ἐπὴν ἄκλητος ἰὼν ἄνθρωπος ἀλαζὼν<br>λυπῇ θύοντας καὶ σπλαγχνεύειν ἐπιθυμῇ,<br>δὴ τότε χρὴ τύπτειν αὐτὸν πλευρῶν τὸ μεταξὺ —"}, {"st": null, "sp": "Χρησμολόγος", "t": "οὐδὲν λέγειν οἶμαί σε."}, {"st": null, "sp": "Πισθέταιρος", "t": "λαβὲ τὸ βιβλίον.<br>καὶ φείδου μηδὲν μηδ᾽ αἰετοῦ ἐν νεφέλῃσιν,<br>μήτ᾽ ἢν Λάμπων ᾖ μήτ᾽ ἢν ὁ μέγας Διοπείθης."}, {"st": null, "sp": "Χρησμολόγος", "t": "καὶ ταῦτ᾽ ἔνεστ᾽ ἐνταῦθα;"}, {"st": null, "sp": "Πισθέταιρος", "t": "λαβὲ τὸ βιβλίον.<br>οὐκ εἶ θύραζ᾽; ἐς κόρακας."}, {"st": null, "sp": "Χρησμολόγος", "t": "οἴμοι δείλαιος."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὔκουν ἑτέρωσε χρησμολογήσεις ἐκτρέχων;"}, {"st": null, "sp": "Μέτων", "t": "ἥκω παρ᾽ ὑμᾶς —"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἕτερον αὖ τουτὶ κακόν.<br>τί δ᾽ αὖ σὺ δράσων; τίς δ᾽ ἰδέα βουλεύματος;<br>τίς ἡ ‘πίνοια, τίς ὁ κόθορνος τῆς ὁδοῦ;"}, {"st": "995", "sp": "Μέτων", "t": "γεωμετρῆσαι βούλομαι τὸν ἀέρα<br>ὑμῖν διελεῖν τε κατὰ γύας."}, {"st": null, "sp": "Πισθέταιρος", "t": "πρὸς τῶν θεῶν<br>σὺ δ᾽ εἶ τίς ἀνδρῶν;"}, {"st": null, "sp": "Μέτων", "t": "ὅστις εἴμ᾽ ἐγώ; Μέτων,<br>ὃν οἶδεν Ἑλλὰς χὠ Κολωνός."}, {"st": null, "sp": "Πισθέταιρος", "t": "εἰπέ μοι,<br>ταυτὶ δέ σοι τί ἔστι;"}, {"st": null, "sp": "Μέτων", "t": "κανόνες ἀέρος.<br>αὐτίκα γὰρ ἀήρ ἐστι τὴν ἰδέαν ὅλος<br>κατὰ πνιγέα μάλιστα. προσθεὶς οὖν ἐγὼ<br>τὸν κανόν᾽, ἄνωθεν τουτονὶ τὸν καμπύλον<br>ἐνθεὶς διαβήτην — μανθάνεις;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ μανθάνω."}, {"st": null, "sp": "Μέτων", "t": "ὀρθῷ μετρήσω κανόνι προστιθείς, ἵνα<br>ὁ κύκλος γένηται σοι τετράγωνος κἀν μέσῳ<br>ἀγορά, φέρουσαι δ᾽ ὦσιν εἰς αὐτὴν ὁδοὶ<br>ὀρθαὶ πρὸς αὐτὸ τὸ μέσον, ὥσπερ δ᾽ ἀστέρος<br>αὐτοῦ κυκλοτεροῦς ὄντος ὀρθαὶ πανταχῇ<br>ἀκτῖνες ἀπολάμπωσιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἅνθρωπος Θαλῆς.<br>Μέτων —"}, {"st": null, "sp": "Μέτων", "t": "τί ἔστιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἶσθ᾽ ὁτιὴ φιλῶ σ᾽ ἐγώ,<br>κἀμοὶ πιθόμενος ὑπαποκίνει τῆς ὁδοῦ."}, {"st": null, "sp": "Μέτων", "t": "τί δ᾽ ἐστὶ δεινόν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὥσπερ ἐν Λακεδαίμονι<br>ξενηλατοῦνται καὶ κεκίνηνταί τινες:<br>πληγαὶ συχναὶ κατ᾽ ἄστυ."}, {"st": null, "sp": "Μέτων", "t": "μῶν στασιάζετε;"}, {"st": "1015", "sp": "Πισθέταιρος", "t": "μὰ τὸν Δί᾽ οὐ δῆτ᾽."}, {"st": null, "sp": "Μέτων", "t": "ἀλλὰ πῶς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁμοθυμαδὸν<br>σποδεῖν ἅπαντας τοὺς ἀλαζόνας δοκεῖ."}, {"st": null, "sp": "Μέτων", "t": "ὑπάγοιμί τἄρ᾽ ἄν."}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ Δί᾽ ὡς οὐκ οἶδ᾽ ἂν εἰ<br>φθαίης ἄν: ἐπίκεινται γὰρ ἐγγὺς αὑταιί."}, {"st": null, "sp": "Μέτων", "t": "οἴμοι κακοδαίμων."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἔλεγον ἐγὼ πάλαι;<br>οὐκ ἀναμετρήσεις σαυτὸν ἀπιὼν ἀλλαχῇ;"}, {"st": null, "sp": "Ἐπίσκοπος", "t": "ποῦ πρόξενοι;"}, {"st": null, "sp": "Πισθέταιρος", "t": "τίς ὁ Σαρδανάπαλλος οὑτοσί;"}, {"st": null, "sp": "Ἐπίσκοπος", "t": "ἐπίσκοπος ἥκω δεῦρο τῷ κυάμῳ λαχὼν<br>ἐς τὰς Νεφελοκοκκυγίας."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐπίσκοπος;<br>ἔπεμψε δὲ τίς σε δεῦρο;"}, {"st": null, "sp": "Ἐπίσκοπος", "t": "φαῦλον βιβλίον<br>Τελέου."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί; βούλει δῆτα τὸν μισθὸν λαβὼν<br>μὴ πράγματ᾽ ἔχειν ἀλλ᾽ ἀπιέναι;"}, {"st": null, "sp": "Ἐπίσκοπος", "t": "νὴ τοὺς θεούς.<br>ἐκκλησιάσαι δ᾽ οὖν ἐδεόμην οἴκοι μένων.<br>ἔστιν γὰρ ἃ δι᾽ ἐμοῦ πέπρακται Φαρνάκῃ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄπιθι λαβών: ἔστιν δ᾽ ὁ μισθὸς οὑτοσί."}, {"st": "1030", "sp": "Ἐπίσκοπος", "t": "τουτὶ τί ἦν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐκκλησία περὶ Φαρνάκου."}, {"st": null, "sp": "Ἐπίσκοπος", "t": "μαρτύρομαι τυπτόμενος ὢν ἐπίσκοπος."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἀποσοβήσεις; οὐκ ἀποίσεις τὼ κάδω;<br>οὐ δεινά; καὶ πέμπουσιν ἤδη ‘πισκόπους<br>ἐς τὴν πόλιν, πρὶν καὶ τεθύσθαι τοῖς θεοῖς;"}, {"st": "1035", "sp": "Ψηφισματοπώλης", "t": "ἐὰν δ᾽ ὁ Νεφελοκοκκυγιεὺς τὸν Ἀθηναῖον ἀδικῇ —"}, {"st": null, "sp": "Πισθέταιρος", "t": "τουτὶ τί ἔστιν αὖ κακὸν τὸ βιβλίον;"}, {"st": null, "sp": "Ψηφισματοπώλης", "t": "ψηφισματοπώλης εἰμὶ καὶ νόμους νέους<br>ἥκω παρ᾽ ὑμᾶς δεῦρο πωλήσων."}, {"st": null, "sp": "Πισθέταιρος", "t": "τὸ τί;"}, {"st": "1040", "sp": "Ψηφισματοπώλης", "t": "χρῆσθαι Νεφελοκοκκυγιᾶς τοῖσδε τοῖς μέτροισι καὶ σταθμοῖσι καὶ ψηφίσμασι καθάπερ Ὀλοφύξιοι."}, {"st": null, "sp": "Πισθέταιρος", "t": "σὺ δέ γ᾽ οἷσπερ ὡτοτύξιοι χρήσει τάχα."}, {"st": null, "sp": "Ψηφισματοπώλης", "t": "οὗτος τί πάσχεις;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἀποίσεις τοὺς νόμους;<br>πικροὺς ἐγώ σοι τήμερον δείξω νόμους."}, {"st": null, "sp": "Ἐπίσκοπος", "t": "καλοῦμαι Πισθέταιρον ὕβρεως ἐς τὸν Μουνιχιῶνα μῆνα."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄληθες οὗτος; ἔτι γὰρ ἐνταῦθ᾽ ἦσθα σύ;"}, {"st": "1050", "sp": "Ψηφισματοπώλης", "t": "ἐὰν δέ τις ἐξελαύνῃ τοὺς ἄρχοντας καὶ μὴ δέχηται κατὰ τὴν στήλην —"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἴμοι κακοδαίμων, καὶ σὺ γὰρ ἐνταῦθ᾽ ἦσθ᾽ ἔτι;"}, {"st": null, "sp": "Ἐπίσκοπος", "t": "ἀπολῶ σε καὶ γράφω σε μυρίας δραχμάς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐγὼ δὲ σοῦ γε τὼ κάδω διασκεδῶ."}, {"st": null, "sp": "Ψηφισματοπώλης", "t": "μέμνησ᾽ ὅτε τῆς στήλης κατετίλας ἑσπέρας;"}, {"st": "1055", "sp": "Πισθέταιρος", "t": "αἰβοῖ: λαβέτω τις αὐτόν. οὗτος οὐ μενεῖς;<br>ἀπίωμεν ἡμεῖς ὡς τάχιστ᾽ ἐντευθενὶ<br>θύσοντες εἴσω τοῖς θεοῖσι τὸν τράγον."}, {"st": null, "sp": "Χορός", "t": "ἤδη ‘μοὶ τῷ παντόπτᾳ<br>καὶ παντάρχᾳ θνητοὶ πάντες<br>θύσουσ᾽ εὐκταίαις εὐχαῖς.<br>πᾶσαν μὲν γὰρ γᾶν ὀπτεύω,<br>σῴζω δ᾽ εὐθαλεῖς καρποὺς<br>κτείνων παμφύλων γένναν<br>θηρῶν, ἂ πάντ᾽ ἐν γαίᾳ<br>ἐκ κάλυκος αὐξανόμενον γένυσι παμφάγοις<br>δένδρεσί τ᾽ ἐφημένα καρπὸν ἀποβόσκεται:<br>κτείνω δ᾽ οἳ κήπους εὐώδεις<br>φθείρουσιν λύμαις ἐχθίσταις,<br>ἑρπετά τε καὶ δάκετα πάνθ᾽ ὅσαπερ<br>ἔστιν ὑπ᾽ ἐμᾶς πτέρυγος ἐν φοναῖς ὄλλυται."}, {"st": null, "sp": "Χορός", "t": "τῇδε μέντοι θἠμέρᾳ μάλιστ᾽ ἐπαναγορεύεται,<br>ἢν ἀποκτείνῃ τις ὑμῶν Διαγόραν τὸν Μήλιον,<br>λαμβάνειν τάλαντον, ἤν τε τῶν τυράννων τίς τινα<br>τῶν τεθνηκότων ἀποκτείνῃ, τάλαντον λαμβάνειν.<br>βουλόμεσθ᾽ οὖν νυν ἀνειπεῖν ταὐτὰ χἠμεῖς ἐνθάδε.<br>ἢν ἀποκτείνῃ τις ὑμῶν Φιλοκράτη τὸν Στρούθιον,<br>λήψεται τάλαντον, ἢν δὲ ζῶντά γ᾽ ἀγάγῃ, τέτταρα,<br>ὅτι συνείρων τοὺς σπίνους πωλεῖ καθ᾽ ἑπτὰ τοὐβολοῦ,<br>εἶτα φυσῶν τὰς κίχλας δείκνυσι καὶ λυμαίνεται,<br>τοῖς τε κοψίχοισιν ἐς τὰς ῥῖνας ἐγχεῖ τὰ πτερά,<br>τὰς περιστεράς θ᾽ ὁμοίως ξυλλαβὼν εἵρξας ἔχει,<br>κἀπαναγκάζει παλεύειν δεδεμένας ἐν δικτύῳ.<br>ταῦτα βουλόμεσθ᾽ ἀνειπεῖν: κεἴ τις ὄρνιθας τρέφει<br>εἱργμένους ὑμῶν ἐν αὐλῇ, φράζομεν μεθιέναι.<br>ἢν δὲ μὴ πίθησθε, συλληφθέντες ὑπὸ τῶν ὀρνέων<br>αὖθις ὑμεῖς αὖ παρ᾽ ἡμῖν δεδεμένοι παλεύσετε."}, {"st": null, "sp": "N", "t": "εὔδαιμον φῦλον πτηνῶν οἰωνῶν, οἳ χειμῶνος μὲν<br>χλαίνας οὐκ ἀμπισχνοῦνται:<br>οὐδ᾽ αὖ θερμὴ πνίγους ἡμᾶς<br>ἀκτὶς τηλαυγὴς θάλπει:<br>ἀλλ᾽ ἀνθηρῶν λειμώνων<br>φύλλων τ᾽ ἐν κόλποις ναίω,<br>ἡνίκ᾽ ἂν ὁ θεσπέσιος ὀξὺ μέλος ἀχέτας<br>θάλπεσι μεσημβρινοῖς ἡλιομανὴς βοᾷ.<br>χειμάζω δ᾽ ἐν κοίλοις ἄντροις<br>νύμφαοις οὐρείαις ξυμπαίζων:<br>ἠρινά τε βοσκόμεθα παρθένια<br>λευκότροφα μύρτα Χαρίτων τε κηπεύματα."}, {"st": null, "sp": "Χορός", "t": "τοῖς κριταῖς εἰπεῖν τι βουλόμεσθα τῆς νίκης πέρι,<br>ὅσ᾽ ἀγάθ᾽, ἢν κρίνωσιν ἡμᾶς, πᾶσιν αὐτοῖς δώσομεν,<br>ὥστε κρείττω δῶρα πολλῷ τῶν Ἀλεξάνδρου λαβεῖν.<br>πρῶτα μὲν γὰρ οὗ μάλιστα πᾶς κριτὴς ἐφίεται,<br>γλαῦκες ὑμᾶς οὔποτ᾽ ἐπιλείψουσι Λαυρειωτικαί:<br>ἀλλ᾽ ἐνοικήσουσιν ἔνδον, ἔν τε τοῖς βαλλαντίοις<br>ἐννεοττεύσουσι κἀκλέψουσι μικρὰ κέρματα.<br>εἶτα πρὸς τούτοισιν ὥσπερ ἐν ἱεροῖς οἰκήσετε:<br>τὰς γὰρ ὑμῶν οἰκίας ἐρέψομεν πρὸς αἰετόν:<br>κἂν λαχόντες ἀρχίδιον εἶθ᾽ ἁρπάσαι βούλησθέ τι,<br>ὀξὺν ἱερακίσκον ἐς τὰς χεῖρας ὑμῖν δώσομεν.<br>ἢν δέ που δειπνῆτε, πρηγορεῶνας ὑμῖν πέμψομεν.<br>ἢν δὲ μὴ κρίνητε, χαλκεύεσθε μηνίσκους φορεῖν<br>ὥσπερ ἀνδριάντες: ὡς ὑμῶν ὃς ἂν μὴ μῆν᾽ ἔχῃ,<br>ὅταν ἔχητε χλανίδα λευκήν, τότε μάλισθ᾽ οὕτω δίκην<br>δώσεθ᾽ ἡμῖν, πᾶσι τοῖς ὄρνισι κατατιλώμενοι."}, {"st": null, "sp": "Χορός", "t": "τὰ μὲν ἱέρ᾽ ἡμῖν ἐστιν ὦρνιθες καλά:<br>ἀλλ᾽ ὡς ἀπὸ τοῦ τείχους πάρεστιν ἄγγελος<br>οὐδείς, ὅτου πευσόμεθα τἀκεῖ πράγματα.<br>ἀλλ᾽ οὑτοσὶ τρέχει τις Ἀλφειὸν πνέων."}, {"st": null, "sp": "Ἄγγελος Α", "t": "ποῦ ποῦ ‘στι, ποῦ ποῦ ποῦ ‘στι, ποῦ ποῦ ποῦ ‘στι ποῦ,<br>ποῦ Πισθέταιρός ἐστιν ἅρχων;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὑτοσί."}, {"st": null, "sp": "Ἄγγελος Α", "t": "ἐξῳκοδόμηταί σοι τὸ τεῖχος."}, {"st": null, "sp": "Πισθέταιρος", "t": "εὖ λέγεις."}, {"st": "1125", "sp": "Ἄγγελος Α", "t": "κάλλιστον ἔργον καὶ μεγαλοπρεπέστατον:<br>ὥστ᾽ ἂν ἐπάνω μὲν Προξενίδης ὁ Κομπασεὺς<br>καὶ Θεογένης ἐναντίω δύ᾽ ἅρματε,<br>ἵππων ὑπόντων μέγεθος ὅσον ὁ δούριος,<br>ὑπὸ τοῦ πλάτους ἂν παρελασαίτην."}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἡράκλεις."}, {"st": "1130", "sp": "Ἄγγελος Α", "t": "τὸ δὲ μῆκός ἐστι, καὶ γὰρ ἐμέτρησ᾽ αὔτ᾽ ἐγώ,<br>ἑκατοντορόγυιον."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ Πόσειδον τοῦ μάκρους.<br>τίνες ᾠκοδόμησαν αὐτὸ τηλικουτονί;"}, {"st": null, "sp": "Ἄγγελος Α", "t": "ὄρνιθες, οὐδεὶς ἄλλος, οὐκ Αἰγύπτιος<br>πλινθοφόρος, οὐ λιθουργός, οὐ τέκτων παρῆν,<br>ἀλλ᾽ αὐτόχειρες, ὥστε θαυμάζειν ἐμέ.<br>ἐκ μέν γε Λιβύης ἧκον ὡς τρισμύριαι<br>γέρανοι θεμελίους καταπεπωκυῖαι λίθους.<br>τούτους δ᾽ ἐτύκιζον αἱ κρέκες τοῖς ῥύγχεσιν.<br>ἕτεροι δ᾽ ἐπλινθοφόρουν πελαργοὶ μύριοι:<br>ὕδωρ δ᾽ ἐφόρουν κάτωθεν ἐς τὸν ἀέρα<br>οἱ χαραδριοὶ καὶ τἄλλα ποτόμι᾽ ὄρνεα."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐπηλοφόρουν δ᾽ αὐτοῖσι τίνες;"}, {"st": null, "sp": "Ἄγγελος Α", "t": "ἐρωδιοὶ<br>λεκάναισι."}, {"st": null, "sp": "Πισθέταιρος", "t": "τὸν δὲ πηλὸν ἐνεβάλλοντο πῶς;"}, {"st": null, "sp": "Ἄγγελος Α", "t": "τοῦτ᾽ ὦγάθ᾽ ἐξηύρητο καὶ σοφώτατα:<br>οἱ χῆνες ὑποτύπτοντες ὥσπερ ταῖς ἄμαις<br>ἐς τὰς λεκάνας ἐνέβαλλον αὐτοῖς τοῖν ποδοῖν."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δῆτα πόδες ἂν οὐκ ἂν ἐργασαίατο;"}, {"st": null, "sp": "Ἄγγελος Α", "t": "καὶ νὴ Δί᾽ αἱ νῆτταί γε περιεζωσμέναι<br>ἐπλινθοφόρουν: ἄνω δὲ τὸν ὑπαγωγέα<br>ἐπέτοντ᾽ ἔχουσαι κατόπιν †ὥσπερ παιδία<br>τὸν πηλὸν ἐν τοῖς στόμασιν† αἱ χελιδόνες."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δῆτα μισθωτοὺς ἂν ἔτι μισθοῖτό τις;<br>φέρ᾽ ἴδω, τί δαί; τὰ ξύλινα τοῦ τείχους τίνες<br>ἀπηργάσαντ᾽;"}, {"st": null, "sp": "Ἄγγελος Α", "t": "ὄρνιθες ἦσαν τέκτονες<br>σοφώτατοι πελεκᾶντες, οἳ τοῖς ῥύγχεσιν<br>ἀπεπελέκησαν τὰς πύλας: ἦν δ᾽ ὁ κτύπος<br>αὐτῶν πελεκώντων ὥσπερ ἐν ναυπηγίῳ.<br>καὶ νῦν ἅπαντ᾽ ἐκεῖνα πεπύλωται πύλαις<br>καὶ βεβαλάνωται καὶ φυλάττεται κύκλῳ,<br>ἐφοδεύεται, κωδωνοφορεῖται, πανταχῇ,<br>φυλακαὶ καθεστήκασι καὶ φρυκτωρίαι<br>ἐν τοῖσι πύργοις. ἀλλ᾽ ἐγὼ μὲν ἀποτρέχων<br>ἀπονίψομαι: σὺ δ᾽ αὐτὸς ἤδη τἄλλα δρᾶ."}, {"st": null, "sp": "Χορός", "t": "οὗτος τί ποιεῖς; ἆρα θαυμάζεις ὅτι<br>οὕτω τὸ τεῖχος ἐκτετείχισται ταχύ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ τοὺς θεοὺς ἔγωγε: καὶ γὰρ ἄξιον:<br>ἴσα γὰρ ἀληθῶς φαίνεταί μοι ψεύδεσιν.<br>ἀλλ᾽ ὅδε φύλαξ γὰρ τῶν ἐκεῖθεν ἄγγελος<br>ἐσθεῖ πρὸς ἡμᾶς δεῦρο πυρρίχην βλέπων."}, {"st": "1170", "sp": "Ἄγγελος Β", "t": "ἰοὺ ἰού, ἰοὺ ἰού, ἰοὺ ἰού."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί τὸ πρᾶγμα τουτί;"}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἄγγελος Β.<br>δεινότατα πεπόνθαμεν.<br>τῶν γὰρ θεῶν τις ἄρτι τῶν παρὰ τοῦ Διὸς<br>διὰ τῶν πυλῶν εἰσέπτετ᾽ ἐς τὸν ἀέρα,<br>λαθὼν κολοιοὺς φύλακας ἡμεροσκόπους."}, {"st": "1175", "sp": "Πισθέταιρος", "t": "ὦ δεινὸν ἔργον καὶ σχέτλιον εἰργασμένος.<br>τίς τῶν θεῶν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἄγγελος Β.<br>οὐκ ἴσμεν: ὅτι δ᾽ εἶχε πτερά,<br>τοῦτ᾽ ἴσμεν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὔκουν δῆτα περιπόλους ἐχρῆν<br>πέμψαι κατ᾽ αὐτὸν εὐθύς;"}, {"st": null, "sp": "Πισθέταιρος", "t": "Ἄγγελος Β.<br>ἀλλ᾽ ἐπέμψαμεν<br>τρισμυρίους ἱέρακας ἱπποτοξότας,<br>χωρεῖ δὲ πᾶς τις ὄνυχας ἠγκυλωμένος,<br>κερχνῂς τριόρχης γὺψ κύμινδις αἰετός:<br>ῥύμῃ τε καὶ πτεροῖσι καὶ ῥοιζήμασιν<br>αἰθὴρ δονεῖται τοῦ θεοῦ ζητουμένου:<br>κἄστ᾽ οὐ μακρὰν ἄπωθεν, ἀλλ᾽ ἐνταῦθά που<br>ἤδη ‘στίν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὔκουν σφενδόνας δεῖ λαμβάνειν<br>καὶ τόξα; χώρει δεῦρο πᾶς ὑπηρέτης:<br>τόξευε παῖε, σφενδόνην τίς μοι δότω."}, {"st": null, "sp": "Χορός", "t": "πόλεμος αἴρεται, πόλεμος οὐ φατὸς<br>πρὸς ἐμὲ καὶ θεούς. ἀλλὰ φύλαττε πᾶς<br>ἀέρα περινέφελον, ὃν ἔρεβος ἐτέκετο,<br>μή σε λάθῃ θεῶν τις ταύτῃ περῶν:"}, {"st": null, "sp": "Χορός", "t": "... ἄθρει δὲ πᾶς κύκλῳ σκοπῶν,<br>ὡς ἐγγὺς ἤδη δαίμονος πεδαρσίου<br>δίνης πτερωτὸς φθόγγος ἐξακούεται."}, {"st": null, "sp": "Πισθέταιρος", "t": "αὕτη σύ, ποῖ ποῖ ποῖ πέτει; μέν᾽ ἥσυχος,<br>ἔχ᾽ ἀτρέμας: αὐτοῦ στῆθ᾽: ἐπίσχες τοῦ δρόμου.<br>τίς εἶ; ποδαπή; λέγειν ἐχρῆν ὁπόθεν πότ᾽ εἶ."}, {"st": null, "sp": "Ἶρις", "t": "παρὰ τῶν θεῶν ἔγωγε τῶν Ὀλυμπίων."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὄνομα δέ σο. τί ἐστι; πλοῖον ἢ κυνῆ;"}, {"st": null, "sp": "Ἶρις", "t": "Ἶρις ταχεῖα."}, {"st": null, "sp": "Πισθέταιρος", "t": "Πάραλος ἢ Σαλαμινία;"}, {"st": "1205", "sp": "Ἶρις", "t": "τί δὲ τοῦτο;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ταυτηνί τις οὐ συλλήψεται<br>ἀναπτόμενος τρίορχος;"}, {"st": null, "sp": "Ἶρις", "t": "ἐμὲ συλλήψεται;<br>τί ποτ᾽ ἐστὶ τουτὶ τὸ κακόν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἰμώξει μακρά."}, {"st": null, "sp": "Ἶρις", "t": "ἄτοπόν γε τουτὶ πρᾶγμα."}, {"st": null, "sp": "Πισθέταιρος", "t": "κατὰ ποίας πύλας<br>εἰσῆλθες ἐς τὸ τεῖχος ὦ μιαρωτάτη;"}, {"st": "1210", "sp": "Ἶρις", "t": "οὐκ οἶδα μὰ Δί᾽ ἔγωγε κατὰ ποίας πύλας."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἤκουσας αὐτῆς οἷον εἰρωνεύεται;<br>πρὸς τοὺς κολοιάρχας προσῆλθες; οὐ λέγεις;<br>σφραγῖδ᾽ ἔχεις παρὰ τῶν πελαργῶν;"}, {"st": null, "sp": "Ἶρις", "t": "τί τὸ κακόν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἔλαβες;"}, {"st": null, "sp": "Ἶρις", "t": "ὑγιαίνεις μέν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐδὲ σύμβολον<br>ἐπέβαλεν ὀρνίθαρχος οὐδείς σοι παρών;"}, {"st": null, "sp": "Ἶρις", "t": "μὰ Δί᾽ οὐκ ἔμοιγ᾽ ἐπέβαλεν οὐδεὶς ὦ μέλε."}, {"st": null, "sp": "Πισθέταιρος", "t": "κἄπειτα δῆθ᾽ οὕτω σιωπῇ διαπέτει<br>διὰ τῆς πόλεως τῆς ἀλλοτρίας καὶ τοῦ χάους;"}, {"st": null, "sp": "Ἶρις", "t": "ποίᾳ γὰρ ἄλλῃ χρὴ πέτεσθαι τοὺς θεούς;"}, {"st": "1220", "sp": "Πισθέταιρος", "t": "οὐκ οἶδα μὰ Δί᾽ ἔγωγε: τῇδε μὲν γὰρ οὔ.<br>ἀδικεῖς δὲ καὶ νῦν. ἆρά γ᾽ οἶσθα τοῦθ᾽ ὅτι<br>δικαιότατ᾽ ἂν ληφθεῖσα πασῶν Ἰρίδων<br>ἀπέθανες, εἰ τῆς ἀξίας ἐτύγχανες;"}, {"st": null, "sp": "Ἶρις", "t": "ἀλλ᾽ ἀθάνατός εἰμ᾽."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ὅμως ἂν ἀπέθανες.<br>δεινότατα γάρ τοι πεισόμεσθ᾽, ἐμοὶ δοκεῖ,<br>εἰ τῶν μὲν ἄλλων ἄρχομεν, ὑμεῖς δ᾽ οἱ θεοὶ<br>ἀκολαστανεῖτε, κοὐδέπω γνώσεσθ᾽ ὅτι<br>ἀκροατέον ὑμῖν ἐν μέρει τῶν κρειττόνων.<br>φράσον δέ τοί μοι τὼ πτέρυγε ποῖ ναυστολεῖς;"}, {"st": "1230", "sp": "Ἶρις", "t": "ἐγώ; πρὸς ἀνθρώπους πέτομαι παρὰ τοῦ πατρὸς<br>φράσουσα θύειν τοῖς Ὀλυμπίοις θεοῖς<br>μηλοσφαγεῖν τε βουθύτοις ἐπ᾽ ἐσχάραις<br>κνισᾶν τ᾽ ἀγυιάς."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί σὺ λέγεις; ποίοις θεοῖς;"}, {"st": null, "sp": "Ἶρις", "t": "ποίοισιν; ἡμῖν τοῖς ἐν οὐρανῷ θεοῖς."}, {"st": "1235", "sp": "Πισθέταιρος", "t": "θεοὶ γὰρ ὑμεῖς;"}, {"st": null, "sp": "Ἶρις", "t": "τίς γάρ ἐστ᾽ ἄλλος θεός;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὄρνιθες ἀνθρώποισι νῦν εἰσιν θεοί,<br>οἷς θυτέον αὐτούς, ἀλλὰ μὰ Δί᾽ οὐ τῷ Διί."}, {"st": null, "sp": "Ἶρις", "t": "ὦ μῶρε μῶρε μὴ θεῶν κίνει φρένας<br>δεινάς, ὅπως μή σου γένος πανώλεθρον<br>Διὸς μακέλλῃ πᾶν ἀναστρέψῃ Δίκη,<br>λιγνὺς δὲ σῶμα καὶ δόμων περιπτυχὰς<br>καταιθαλώσῃ σου Λικυμνίαις βολαῖς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄκουσον αὕτη: παῦε τῶν παφλασμάτων:<br>ἔχ᾽ ἀτρέμα. φέρ᾽ ἴδω, πότερα Λυδὸν ἢ Φρύγα<br>ταυτὶ λέγουσα μορμολύττεσθαι δοκεῖς;<br>ἆρ᾽ οἶσθ᾽ ὅτι Ζεὺς εἴ με λυπήσει πέρα,<br>μέλαθρα μὲν αὐτοῦ καὶ δόμους Ἀμφίονος<br>καταιθαλώσω πυρφόροισιν αἰετοῖς;<br>πέμψω δὲ πορφυρίωνας ἐς τὸν οὐρανὸν<br>ὄρνις ἐπ᾽ αὐτὸν παρδαλᾶς ἐνημμένους<br>πλεῖν ἑξακοσίους τὸν ἀριθμόν. καὶ δή ποτε<br>εἷς Πορφυρίων αὐτῷ παρέσχε πράγματα.<br>σὺ δ᾽ εἴ με λυπήσεις τι, τῆς διακόνου<br>πρώτης ἀνατείνας τὼ σκέλει διαμηριῶ<br>τὴν Ἶριν αὐτήν, ὥστε θαυμάζειν ὅπως<br>οὕτω γέρων ὢν στύομαι τριέμβολον."}, {"st": null, "sp": "Ἶρις", "t": "διαρραγείης ὦ μέλ᾽ αὐτοῖς ῥήμασιν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἀποσοβήσεις; οὐ ταχέως; εὐρὰξ πατάξ."}, {"st": null, "sp": "Ἶρις", "t": "ἦ μήν σε παύσει τῆς ὕβρεως οὑμὸς πατήρ."}, {"st": "1260", "sp": "Πισθέταιρος", "t": "οἴμοι τάλας. οὔκουν ἑτέρωσε πετομένη<br>καταιθαλώσεις τῶν νεωτέρων τινά;"}, {"st": null, "sp": "N", "t": "ἀποκεκλῄκαμεν διογενεῖς θεοὺς μηκέτι τὴν ἐμὴν διαπερᾶν πόλιν,<br>μηδέ γέ τιν᾽ ἱερόθυτον ἀνὰ δάπεδον ἔτι<br>τῇδε βροτῶν θεοῖσι πέμπειν καπνόν."}, {"st": null, "sp": "Πισθέταιρος", "t": "δεινόν γε τὸν κήρυκα τὸν παρὰ τοὺς βροτοὺς<br>οἰχόμενον, εἰ μηδέποτε νοστήσει πάλιν."}, {"st": null, "sp": "Κῆρυξ", "t": "ὦ Πισθέταιρ᾽ ὦ μακάρι᾽ ὦ σοφώτατε,<br>ὦ κλεινότατ᾽ ὦ σοφώτατ᾽ ὦ γλαφυρώτατε,<br>ὦ τρισμακάρι᾽ ὦ κατακέλευσον."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί σὺ λέγεις;"}, {"st": null, "sp": "Κῆρυξ", "t": "στεφάνῳ σε χρυσῷ τῷδε σοφίας οὕνεκα<br>στεφανοῦσι καὶ τιμῶσιν οἱ πάντες λεῴ."}, {"st": null, "sp": "N", "t": "δέχομαι. τί δ᾽ οὕτως οἱ λεῲ τιμῶσί με;"}, {"st": null, "sp": "Κῆρυξ", "t": "ὦ κλεινοτάτην αἰθέριον οἰκίσας πόλιν,<br>οὐκ οἷσθ᾽ ὅσην τιμὴν παρ᾽ ἀνθρώποις φέρει,<br>ὅσους τ᾽ ἐραστὰς τῆσδε τῆς χώρας ἔχεις.<br>πρὶν μὲν γὰρ οἰκίσαι σε τήνδε τὴν πόλιν,<br>ἐλακωνομάνουν ἅπαντες ἄνθρωποι τότε,<br>ἐκόμων ἐπείνων ἐρρύπων ἐσωκράτουν<br>σκυτάλι᾽ ἐφόρουν, νυνὶ δ᾽ ὑποστρέψαντες αὖ<br>ὀρνιθομανοῦσι, πάντα δ᾽ ὑπὸ τῆς ἡδονῆς<br>ποιοῦσιν ἅπερ ὄρνιθες ἐκμιμούμενοι:<br>πρῶτον μὲν εὐθὺς πάντες ἐξ εὐνῆς ἅμα<br>ἐπέτονθ᾽ ἕωθεν ὥσπερ ἡμεῖς ἐπὶ νομόν:<br>κἄπειτ᾽ ἂν ἅμα κατῆραν ἐς τὰ βιβλία:<br>εἶτ᾽ ἀπενέμοντ᾽ ἐνταῦθα τὰ ψηφίσματα.<br>ὠρνιθομάνουν δ᾽ οὕτω περιφανῶς ὥστε καὶ<br>πολλοῖσιν ὀρνίθων ὀνόματ᾽ ἦν κείμενα.<br>πέρδιξ μὲν εἷς κάπηλος ὠνομάζετο<br>χωλός, Μενίππῳ δ᾽ ἦν χελιδὼν τοὔνομα,<br>Ὀπουντίῳ δ᾽ ὀφθαλμὸν οὐκ ἔχων κόραξ,<br>κορυδὸς Φιλοκλέει, χηναλώπηξ Θεογένει,<br>ἶβις Λυκούργῳ, Χαιρεφῶντι νυκτερίς,<br>Συρακοσίῳ δὲ κίττα: Μειδίας δ᾽ ἐκεῖ<br>ὄρτυξ ἐκαλεῖτο: καὶ γὰρ ᾔκειν ὄρτυγι<br>ὑπὸ στυφοκόπου τὴν κεφαλὴν πεπληγμένῳ.<br>ᾖδον δ᾽ ὑπὸ φιλορνιθίας πάντες μέλη,<br>ὅπου χελιδὼν ἦν τις ἐμπεποιημένη<br>ἢ πηνέλοψ ἢ χήν τις ἢ περιστερὰ<br>ἢ πτέρυγες, ἢ πτεροῦ τι καὶ σμικρὸν προσῆν.<br>τοιαῦτα μὲν τἀκεῖθεν. ἓν δέ σοι λέγω:<br>ἥξουσ᾽ ἐκεῖθεν δεῦρο πλεῖν ἢ μύριοι<br>πτερῶν δεόμενοι καὶ τρόπων γαμψωνύχων:<br>ὥστε πτερῶν σοι τοῖς ἐποίκοις δεῖ ποθέν."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἆρα μὰ Δί᾽ ἡμῖν ἔτ᾽ ἔργον ἑστάναι.<br>ἀλλ᾽ ὡς τάχιστα σὺ μὲν ἰὼν τὰς ἀρρίχους<br>καὶ τοὺς κοφίνους ἅπαντας ἐμπίμπλη πτερῶν:<br>Μανῆς δὲ φερέτω μοι θύραζε τὰ πτερά:<br>ἐγὼ δ᾽ ἐκείνων τοὺς προσιόντας δέξομαι."}, {"st": null, "sp": "Χορός", "t": "ταχὺ δὴ πολυάνορα τάνδε πόλιν<br>καλεῖ τις ἀνθρώπων."}, {"st": "1315", "sp": "Πισθέταιρος", "t": "τύχη μόνον προσείη."}, {"st": null, "sp": "Χορός", "t": "κατέχουσι δ᾽ ἔρωτες ἐμᾶς πόλεως."}, {"st": null, "sp": "Πισθέταιρος", "t": "θάττον φέρειν κελεύω."}, {"st": null, "sp": "Χορός", "t": "τί γὰρ οὐκ ἔνι ταύτῃ<br>καλὸν ἀνδρὶ μετοικεῖν;<br>Σοφία Πόθος Ἀμβροσία Χάριτες<br>τό τε τῆς ἀγανόφρονος Ἡσυχίας<br>εὐήμερον πρόσωπον."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὡς βλακικῶς διακονεῖς: οὐ θᾶττον ἐγκονήσεις;"}, {"st": "1325", "sp": "Χορός", "t": "φερέτω κάλαθον ταχύ τις πτερύγων,<br>σὺ δ᾽ αὖθις ἐξόρμα —"}, {"st": null, "sp": "Πισθέταιρος", "t": "τύπτων γε τοῦτον ὡδί."}, {"st": null, "sp": "Χορός", "t": "πάνυ γὰρ βραδύς ἐστί τις ὥσπερ ὄνος."}, {"st": null, "sp": "Πισθέταιρος", "t": "Μανῆς γάρ ἐστι δειλός."}, {"st": "1330", "sp": "Χορός", "t": "σὺ δὲ τὰ πτερὰ πρῶτον<br>διάθες τάδε κόσμῳ,<br>τά τε μουσίχ᾽ ὁμοῦ τά τε μαντικὰ καὶ<br>τὰ θαλάττι᾽. ἔπειτα δ᾽ ὅπως φρονίμως<br>πρὸς ἄνδρ᾽ ὁρῶν πτερώσεις."}, {"st": "1335", "sp": "Πισθέταιρος", "t": "οὔ τοι μὰ τὰς κερχνῇδας ἔτι σοῦ σχήσομαι,<br>οὕτως ὁρῶν σε δειλὸν ὄντα καὶ βραδύν."}, {"st": null, "sp": "Πατραλοίας", "t": "γενοίμαν αἰετὸς ὑψιπέτας,<br>ὡς ἀμποταθείην ὑπὲρ ἀτρυγέτου<br>γλαυκᾶς ἐπ᾽ οἶδμα λίμνας."}, {"st": "1340", "sp": "Πισθέταιρος", "t": "ἔοικεν οὐ ψευδαγγελήσειν ἅγγελος.<br>ᾁδων γὰρ ὅδε τις αἰετοὺς προσέρχεται."}, {"st": null, "sp": "Πατραλοίας", "t": "αἰβοῖ:<br>οὐκ ἔστιν οὐδὲν τοῦ πέτεσθαι γλυκύτερον:<br>ὀρνιθομανῶ γὰρ καὶ πέτομαι καὶ βούλομαι<br>οἰκεῖν μεθ᾽ ὑμῶν κἀπιθυμῶ τῶν νόμων."}, {"st": null, "sp": "Πισθέταιρος", "t": "ποίων νόμων; πολλοὶ γὰρ ὀρνίθων νόμοι."}, {"st": null, "sp": "Πατραλοίας", "t": "πάντων: μάλιστα δ᾽ ὅτι καλὸν νομίζεται<br>τὸν πατέρα τοῖς ὄρνισιν ἄγχειν καὶ δάκνειν."}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ νὴ Δί᾽ ἀνδρεῖόν γε πάνυ νομιζομεν,<br>ὃς ἂν πεπλήγῃ τὸν πατέρα νεοττὸς ὤν."}, {"st": null, "sp": "Πατραλοίας", "t": "διὰ ταῦτα μέντοι δεῦρ᾽ ἀνοικισθεὶς ἐγὼ<br>ἄγχειν ἐπιθυμῶ τὸν πατέρα καὶ πάντ᾽ ἔχειν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ἔστιν ἡμῖν τοῖσιν ὄρνισιν νόμος<br>παλαιὸς ἐν ταῖς τῶν πελαργῶν κύρβεσιν:<br>ἐπὴν ὁ πατὴρ ὁ πελαργὸς ἐκπετησίμους<br>πάντας ποιήσῃ τοὺς πελαργιδέας τρέφων,<br>δεῖ τοὺς νεοττοὺς τὸν πατέρα πάλιν τρέφειν."}, {"st": null, "sp": "Πατραλοίας", "t": "ἀπέλαυσά τἄρα νὴ Δί᾽ ἐλθὼν ἐνθαδί,<br>εἴπερ γέ μοι καὶ τὸν πατέρα βοσκητέον."}, {"st": "1360", "sp": "Πισθέταιρος", "t": "οὐδέν γ᾽. ἐπειδήπερ γὰρ ἦλθες ὦ μέλε<br>εὔνους, πτερώσω σ᾽ ὥσπερ ὄρνιν ὀρφανόν.<br>σοὶ δ᾽ ὦ νεανίσκ᾽ οὐ κακῶς ὑποθήσομαι,<br>ἀλλ᾽ οἷάπερ αὐτὸς ἔμαθον ὅτε παῖς ἦ. σὺ γὰρ<br>τὸν μὲν πατέρα μὴ τύπτε: ταυτηνδὶ λαβὼν<br>τὴν πτέρυγα καὶ τουτὶ τὸ πλῆκτρον θἀτέρᾳ,<br>νομίσας ἀλεκτρυόνος ἔχειν τονδὶ λόφον,<br>φρούρει στρατεύου μισθοφορῶν σαυτὸν τρέφε,<br>τὸν πατέρ ἔα ζῆν: ἀλλ᾽ ἐπειδὴ μάχιμος εἶ,<br>ἐς τἀπὶ Θρᾴκης ἀποπέτου κἀκεῖ μάχου."}, {"st": "1370", "sp": "Πατραλοίας", "t": "νὴ τὸν Διόνυσον εὖ γέ μοι δοκεῖς λέγειν,<br>καὶ πείσομαί σοι."}, {"st": null, "sp": "Πισθέταιρος", "t": "νοῦν ἄρ᾽ ἔξεις νὴ Δία."}, {"st": null, "sp": "Κινησίας", "t": "ἀναπέτομαι δὴ πρὸς Ὄλυμπον πτερύγεσσι κούφαις:<br>πέτομαι δ᾽ ὁδὸν ἄλλοτ᾽ ἐπ᾽ ἄλλαν μελέων —"}, {"st": "1375", "sp": "Πισθέταιρος", "t": "τουτὶ τὸ πρᾶγμα φορτίου δεῖται πτερῶν."}, {"st": null, "sp": "Κινησίας", "t": "ἀφόβῳ φρενὶ σώματί τε νέαν ἐφέπων —"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀσπαζόμεσθα φιλύρινον Κινησίαν.<br>τί δεῦρο πόδα σὺ κυλλὸν ἀνὰ κύκλον κυκλεῖς;"}, {"st": "1380", "sp": "Κινησίας", "t": "ὄρνις γενέσθαι βούλομαι λιγύφθογγος ἀηδών."}, {"st": null, "sp": "Πισθέταιρος", "t": "παῦσαι μελῳδῶν, ἀλλ᾽ ὅ τι λέγεις εἰπέ μοι."}, {"st": null, "sp": "Κινησίας", "t": "ὑπὸ σοῦ πτερωθεὶς βούλομαι μετάρσιος<br>ἀναπτόμενος ἐκ τῶν νεφελῶν καινὰς λαβεῖν<br>ἀεροδονήτους καὶ νιφοβόλους ἀναβολάς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐκ τῶν νεφελῶν γὰρ ἄν τις ἀναβολὰς λάβοι;"}, {"st": null, "sp": "Κινησίας", "t": "κρέμαται μὲν οὖν ἐντεῦθεν ἡμῶν ἡ τέχνη.<br>τῶν διθυράμβων γὰρ τὰ λαμπρὰ γίγνεται<br>ἀέρια καὶ σκότιά γε καὶ κυαναυγέα<br>καὶ πτεροδόνητα: σὺ δὲ κλύων εἴσει τάχα."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ δῆτ᾽ ἔγωγε."}, {"st": null, "sp": "Κινησίας", "t": "νὴ τὸν Ἡρακλέα σύ γε.<br>ἅπαντα γὰρ δίειμί σοι τὸν ἀέρα."}, {"st": null, "sp": "N", "t": "εἴδωλα πετεινῶν αἰθεροδρόμων<br>οἰωνῶν ταναοδείρων —"}, {"st": "1395", "sp": "Πισθέταιρος", "t": "ὠόπ."}, {"st": null, "sp": "N", "t": "τὸν ἁλάδρομον ἁλάμενος ἅμ᾽ ἀνεμων πνοαῖσι βαίην."}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ τὸν Δί᾽ ἦ ‘γώ σου καταπαύσω τὰς πνοάς."}, {"st": null, "sp": "Κινησίας", "t": "τοτὲ μὲν νοτίαν στείχων πρὸς ὁδόν,<br>τοτὲ δ᾽ αὖ βορέᾳ σῶμα πελάζων<br>ἀλίμενον αἰθέρος αὔλακα τέμνων."}, {"st": null, "sp": "Κινησίας", "t": "χαρίεντά γ᾽ ὦ πρεσβῦτ᾽ ἐσοφίσω καὶ σοφά."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ γὰρ σὺ χαίρεις πτεροδόνητος γενόμενος;"}, {"st": null, "sp": "Κινησίας", "t": "ταυτὶ πεποίηκας τὸν κυκλιοδιδάσκαλον,<br>ὂς ταῖσι φυλαῖς περιμάχητός εἰμ᾽ ἀεί;"}, {"st": "1405", "sp": "Πισθέταιρος", "t": "βούλει διδάσκειν καὶ παρ᾽ ἡμῖν οὖν μένων<br>Λεωτροφίδῃ χορὸν πετομένων ὀρνέων<br>Κεκροπίδα φυλήν;"}, {"st": null, "sp": "Κινησίας", "t": "καταγελᾷς μου, δῆλος εἶ.<br>ἀλλ᾽ οὖν ἔγωγ᾽ οὐ παύσομαι, τοῦτ᾽ ἴσθ᾽ ὅτι,<br>πρὶν ἂν πτερωθεὶς διαδράμω τὸν ἀέρα."}, {"st": "1410", "sp": "Συκοφάντης", "t": "ὄρνιθες τίνες οὐδὲν ἔχοντες πτεροποίκιλοι,<br>τανυσίπτερε ποικίλα χελιδοῖ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "τουτὶ τὸ κακὸν οὐ φαῦλον ἐξεγρήγορεν.<br>ὅδ᾽ αὖ μινυρίζων δεῦρό τις προσέρχεται."}, {"st": "1415", "sp": "Συκοφάντης", "t": "τανυσίπτερε ποικίλα μάλ᾽ αὖθις."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐς θοἰμάτιον τὸ σκόλιον ᾁδειν μοι δοκεῖ,<br>δεῖσθαι δ᾽ ἔοικεν οὐκ ὀλίγων χελιδόνων."}, {"st": null, "sp": "Συκοφάντης", "t": "τίς ὁ πτερῶν δεῦρ᾽ ἐστὶ τοὺς ἀφικνουμένους;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁδὶ πάρεστιν: ἀλλ᾽ ὅτου δεῖ χρὴ λέγειν."}, {"st": "1420", "sp": "Συκοφάντης", "t": "πτερῶν πτερῶν δεῖ: μὴ πύθῃ τὸ δεύτερον."}, {"st": null, "sp": "Πισθέταιρος", "t": "μῶν εὐθὺ Πελλήνης πέτεσθαι διανοεῖ;"}, {"st": null, "sp": "Συκοφάντης", "t": "μὰ Δί᾽ ἀλλὰ κλητήρ εἰμι νησιωτικὸς<br>καὶ συκοφάντης —"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ μακάριε τῆς τέχνης."}, {"st": null, "sp": "Συκοφάντης", "t": "καὶ πραγματοδίφης. εἶτα δέομαι πτερὰ λαβὼν<br>κύκλῳ περισοβεῖν τὰς πόλεις καλούμενος."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὑπὸ πτερύγων τι προσκαλεῖ σοφώτερον;"}, {"st": null, "sp": "Συκοφάντης", "t": "μὰ Δί᾽ ἀλλ᾽ ἵν᾽ οἱ λῃσταί τε μὴ λυπῶσί με,<br>μετὰ τῶν γεράνων τ᾽ ἐκεῖθεν ἀναχωρῶ πάλιν,<br>ἀνθ᾽ ἕρματος πολλὰς καταπεπωκὼς δίκας."}, {"st": "1430", "sp": "Πισθέταιρος", "t": "τουτὶ γὰρ ἐργάζει σὺ τοὔργον; εἰπέ μοι,<br>νεανίας ὢν συκοφαντεῖς τοὺς ξένους;"}, {"st": null, "sp": "Συκοφάντης", "t": "τί γὰρ πάθω; σκάπτειν γὰρ οὐκ ἐπίσταμαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ἔστιν ἕτερα νὴ Δί᾽ ἔργα σώφρονα,<br>ἀφ᾽ ὧν διαζῆν ἄνδρα χρῆν τοσουτονὶ<br>ἐκ τοῦ δικαίου μᾶλλον ἢ δικορραφεῖν."}, {"st": null, "sp": "Συκοφάντης", "t": "ὦ δαιμόνιε μὴ νουθέτει μ᾽ ἀλλὰ πτέρου."}, {"st": null, "sp": "Πισθέταιρος", "t": "νῦν τοι λέγων πτερῶ σε."}, {"st": null, "sp": "Συκοφάντης", "t": "καὶ πῶς ἂν λόγοις<br>ἄνδρα πτερώσειας σύ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "πάντες τοῖς λόγοις<br>ἀναπτεροῦνται."}, {"st": null, "sp": "Συκοφάντης", "t": "πάντες;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκ ἀκήκοας,<br>ὅταν λέγωσιν οἱ πατέρες ἑκάστοτε<br>τοῖς μειρακίοις ἐν τοῖσι κουρείοις ταδί;<br>‘δεινῶς γέ μου τὸ μειράκιον Διειτρέφης<br>λέγων ἀνεπτέρωκεν ὥσθ᾽ ἱππηλατεῖν.’<br>ὁ δέ τις τὸν αὑτοῦ φησιν ἐπὶ τραγῳδίᾳ<br>ἀνεπτερῶσθαι καὶ πεποτῆσθαι τὰς φρένας."}, {"st": null, "sp": "Συκοφάντης", "t": "λόγοισί τἄρα καὶ πτεροῦνται;"}, {"st": null, "sp": "Πισθέταιρος", "t": "φήμ᾽ ἐγώ.<br>ὑπὸ γὰρ λόγων ὁ νοῦς τε μετεωρίζεται<br>ἐπαίρεταί τ᾽ ἄνθρωπος. οὕτω καί σ᾽ ἐγὼ<br>ἀναπτερώσας βούλομαι χρηστοῖς λόγοις<br>τρέψαι πρὸς ἔργον νόμιμον."}, {"st": null, "sp": "Συκοφάντης", "t": "ἀλλ᾽ οὐ βούλομαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δαὶ ποιήσεις;"}, {"st": null, "sp": "Συκοφάντης", "t": "τὸ γένος οὐ καταισχυνῶ.<br>παππῷος ὁ βίος συκοφαντεῖν ἐστί μοι.<br>ἀλλὰ πτέρου με ταχέσι καὶ κούφοις πτεροῖς<br>ἱέρακος ἢ κερχνῇδος, ὡς ἂν τοὺς ξένους<br>καλεσάμενος κᾆτ᾽ ἐγκεκληκὼς ἐνθαδὶ<br>κατ᾽ αὖ πέτωμαι πάλιν ἐκεῖσε."}, {"st": null, "sp": "Πισθέταιρος", "t": "μανθάνω.<br>ὡδὶ λέγεις: ὅπως ἂν ὠφλήκῃ δίκην<br>ἐνθάδε πρὶν ἥκειν ὁ ξένος."}, {"st": null, "sp": "Συκοφάντης", "t": "πάνυ μανθάνεις."}, {"st": null, "sp": "Πισθέταιρος", "t": "κἄπειθ᾽ ὁ μὲν πλεῖ δεῦρο, σὺ δ᾽ ἐκεῖσ᾽ αὖ πέτει<br>ἁρπασόμενος τὰ χρήματ᾽ αὐτοῦ."}, {"st": null, "sp": "Συκοφάντης", "t": "πάντ᾽ ἔχεις.<br>βέμβικος οὐδὲν διαφέρειν δεῖ."}, {"st": null, "sp": "Πισθέταιρος", "t": "μανθάνω<br>βέμβικα: καὶ μὴν ἔστι μοι νὴ τὸν Δία<br>κάλλιστα Κορκυραῖα τοιαυτὶ πτερά."}, {"st": null, "sp": "Συκοφάντης", "t": "οἴμοι τάλας μάστιγ᾽ ἔχεις."}, {"st": null, "sp": "Πισθέταιρος", "t": "πτερὼ μὲν οὖν,<br>οἷσί σε ποιήσω τήμερον βεμβικιᾶν."}, {"st": null, "sp": "Συκοφάντης", "t": "οἴμοι τάλας."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ πτερυγιεῖς ἐντευθενί;<br>οὐκ ἀπολιβάξεις ὦ κάκιστ᾽ ἀπολούμενος;<br>πικρὰν τάχ᾽ ὄψει στρεψοδικοπανουργίαν.<br>ἀπίωμεν ἡμεῖς ξυλλαβόντες τὰ πτερά."}, {"st": "1470", "sp": "Χορός", "t": "πολλὰ δὴ καὶ καινὰ καὶ θαυμάστ᾽<br>ἐπεπτόμεσθα καὶ<br>δεινὰ πράγματ᾽ εἴδομεν.<br>ἔστι γὰρ δένδρον πεφυκὸς<br>ἔκτοπόν τι Καρδίας ἀ-<br>πωτέρω Κλεώνυμος,<br>χρήσιμον μὲν οὐδέν, ἄλλως<br>δὲ δειλὸν καὶ μέγα.<br>τοῦτο τοῦ μὲν ἦρος ἀεὶ<br>βλαστάνει καὶ συκοφαντεῖ,<br>τοῦ δὲ χειμῶνος πάλιν τὰς<br>ἀσπίδας φυλλορροεῖ."}, {"st": null, "sp": "Χορός", "t": "ἔστι δ᾽ αὗ χώρα πρὸς αὐτῷ<br>τῷ σκότῳ πόρρω τις ἐν<br>τῇ λύχνων ἐρημίᾳ,<br>ἔνθα τοῖς ἥρωσιν ἄνθρωποι<br>ξυναριστῶσι καὶ ξύν-<br>εισι πλὴν τῆς ἑσπέρας.<br>τηνικαῦτα δ᾽ οὐκέτ᾽ ἦν<br>ἀσφαλὲς ξυντυγχάνειν.<br>εἰ γὰρ ἐντύχοι τις ἥρῳ<br>τῶν βροτῶν νύκτωρ Ὀρέστῃ,<br>γυμνὸς ἦν πληγεὶς ὑπ᾽ αὐτοῦ<br>πάντα τἀπιδέξια."}, {"st": null, "sp": "Χορός", "t": "οἴμοι τάλας, ὁ Ζεὺς ὅπως μή μ᾽ ὄψεται.<br>ποῦ Πισθέταιρός ἐστ᾽;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔα τουτὶ τί ἦν;<br>τίς ὁ συγκαλυμμός;"}, {"st": null, "sp": "Προμηθεύς", "t": "τῶν θεῶν ὁρᾷς τινα<br>ἐμοῦ κατόπιν ἐνταῦθα;"}, {"st": null, "sp": "Πισθέταιρος", "t": "μὰ Δί᾽ ἐγὼ μὲν οὔ.<br>τίς δ᾽ εἶ σύ;"}, {"st": null, "sp": "Προμηθεύς", "t": "πηνίκ᾽ ἐστὶν ἄρα τῆς ἡμέρας;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁπηνίκα; σμικρόν τι μετὰ μεσημβρίαν.<br>ἀλλὰ σὺ τίς εἶ;"}, {"st": null, "sp": "Προμηθεύς", "t": "βουλυτὸς ἢ περαιτέρω;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἴμ᾽ ὡς βδελύττομαί σε."}, {"st": null, "sp": "Προμηθεύς", "t": "τί γὰρ ὁ Ζεὺς ποιεῖ;<br>ἀπαιθριάζει τὰς νεφέλας ἢ ξυννέφει;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οἴμωζε μεγάλ᾽."}, {"st": null, "sp": "Προμηθεύς", "t": "οὕτω μὲν ἐκκεκαλύψομαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ φίλε Προμηθεῦ."}, {"st": null, "sp": "Προμηθεύς", "t": "παῦε παῦε, μὴ βόα."}, {"st": "1505", "sp": "Πισθέταιρος", "t": "τί γὰρ ἔστι;"}, {"st": null, "sp": "Προμηθεύς", "t": "σίγα, μὴ κάλει μου τοὔνομα:<br>ἀπὸ γάρ μ᾽ ὀλεῖς, εἴ μ᾽ ἐνθάδ᾽ ὁ Ζεὺς ὄψεται.<br>ἀλλ᾽ ἵνα φράσω σοι πάντα τἄνω πράγματα,<br>τουτὶ λαβών μου τὸ σκιάδειον ὑπέρεχε<br>ἄνωθεν, ὡς ἂν μή μ᾽ ὁρῶσιν οἱ θεοί."}, {"st": "1510", "sp": "Πισθέταιρος", "t": "ἰοὺ ἰού:<br>εὖ γ᾽ ἐπενόησας αὐτὸ καὶ προμηθικῶς.<br>ὑπόδυθι ταχὺ δὴ κᾆτα θαρρήσας λέγε."}, {"st": null, "sp": "Προμηθεύς", "t": "ἄκουε δή νυν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὡς ἀκούοντος λέγε."}, {"st": null, "sp": "Προμηθεύς", "t": "ἀπόλωλεν ὁ Ζεύς."}, {"st": null, "sp": "Πισθέταιρος", "t": "πηνίκ᾽ ἄττ᾽ ἀπώλετο;"}, {"st": "1515", "sp": "Προμηθεύς", "t": "ἐξ οὗπερ ὑμεῖς ᾠκίσατε τὸν ἀέρα.<br>θύει γὰρ οὐδεὶς οὐδὲν ἀνθρώπων ἔτι<br>θεοῖσιν, οὐδὲ κνῖσα μηρίων ἄπο<br>ἀνῆλθεν ὡς ἡμᾶς ἀπ᾽ ἐκείνου τοῦ χρόνου,<br>ἀλλ᾽ ὡσπερεὶ Θεσμοφορίοις νηστεύομεν<br>ἄνευ θυηλῶν: οἱ δὲ βάρβαροι θεοὶ<br>πεινῶντες ὥσπερ Ἰλλυριοὶ κεκριγότες<br>ἐπιστρατεύσειν φάσ᾽ ἄνωθεν τῷ Διί,<br>εἰ μὴ παρέξει τἀμπόρι᾽ ἀνεῳγμένα,<br>ἵν᾽ εἰσάγοιτο σπλάγχνα κατατετμημένα."}, {"st": "1525", "sp": "Πισθέταιρος", "t": "εἰσὶν γὰρ ἕτεροι βάρβαροι θεοί τινες<br>ἄνωθεν ὑμῶν;"}, {"st": null, "sp": "Προμηθεύς", "t": "οὐ γάρ εἰσι βάρβαροι,<br>ὅθεν ὁ πατρῷός ἐστιν Ἐξηκεστίδῃ;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὄνομα δὲ τούτοις τοῖς θεοῖς τοῖς βαρβάροις<br>τί ἔστιν;"}, {"st": null, "sp": "Προμηθεύς", "t": "ὅ τι ἔστιν; Τριβαλλοί."}, {"st": null, "sp": "Πισθέταιρος", "t": "μανθάνω.<br>ἐντεῦθεν ἆρα τοὐπιτριβείης ἐγένετο;"}, {"st": null, "sp": "Προμηθεύς", "t": "μάλιστα πάντων. ἓν δέ σοι λέγω σαφές:<br>ἥξουσι πρέσβεις δεῦρο περὶ διαλλαγῶν<br>παρὰ τοῦ Διὸς καὶ τῶν Τριβαλλῶν τῶν ἄνω:<br>ὑμεῖς δὲ μὴ σπένδεσθ᾽, ἐὰν μὴ παραδιδῷ<br>τὸ σκῆπτρον ὁ Ζεὺς τοῖσιν ὄρνισιν πάλιν,<br>καὶ τὴν Βασίλειάν σοι γυναῖκ᾽ ἔχειν διδῷ."}, {"st": null, "sp": "Πισθέταιρος", "t": "τίς ἐστιν ἡ Βασίλεια;"}, {"st": null, "sp": "Προμηθεύς", "t": "καλλίστη κόρη,<br>ἥπερ ταμιεύει τὸν κεραυνὸν τοῦ Διὸς<br>καὶ τἄλλ᾽ ἁπαξάπαντα, τὴν εὐβουλίαν<br>τὴν εὐνομίαν τὴν σωφροσύνην τὰ νεώρια,<br>τὴν λοιδορίαν τὸν κωλακρέτην τὰ τριώβολα."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἅπαντά γ᾽ ἆρ᾽ αὐτῷ ταμιεύει;"}, {"st": null, "sp": "Προμηθεύς", "t": "φήμ᾽ ἐγώ.<br>ἥν γ᾽ ἢν σὺ παρ᾽ ἐκείνου παραλάβῃς, πάντ᾽ ἔχεις.<br>τούτων ἕνεκα δεῦρ᾽ ἦλθον, ἵνα φράσαιμί σοι.<br>ἀεί ποτ᾽ ἀνθρώποις γὰρ εὔνους εἴμ᾽ ἐγώ."}, {"st": null, "sp": "Πισθέταιρος", "t": "μόνον θεῶν γὰρ διὰ σ᾽ ἀπανθρακίζομεν."}, {"st": null, "sp": "Προμηθεύς", "t": "μισῶ δ᾽ ἅπαντας τοὺς θεούς, ὡς οἶσθα σύ."}, {"st": null, "sp": "Πισθέταιρος", "t": "νὴ τὸν Δί᾽ ἀεὶ δῆτα θεομισὴς ἔφυς."}, {"st": null, "sp": "Προμηθεύς", "t": "Τίμων καθαρός. ἀλλ᾽ ὡς ἂν ἀποτρέχω πάλιν,<br>φέρε τὸ σκιάδειον, ἵνα με κἂν ὁ Ζεὺς ἴδῃ<br>ἄνωθεν, ἀκολουθεῖν δοκῶ κανηφόρῳ."}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ τὸν δίφρον γε διφροφόρει τονδὶ λαβών."}, {"st": null, "sp": "Χορός", "t": "πρὸς δὲ τοῖς Σκιάποσιν λίμνη<br>τις ἔστ᾽ ἄλουτος οὗ<br>ψυχαγωγεῖ Σωκράτης:<br>ἔνθα καὶ Πείσανδρος ἦλθε<br>δεόμενος ψυχὴν ἰδεῖν ἣ<br>ζῶντ᾽ ἐκεῖνον προὔλιπε,<br>σφάγι᾽ ἔχων κάμηλον ἀμνόν<br>τιν᾽, ἧς λαιμοὺς τεμὼν ὥσπερ<br>ποθ᾽ οὑδυσσεὺς ἀπῆλθε,<br>κᾆτ᾽ ἀνῆλθ᾽ αὐτῷ κάτωθεν<br>πρὸς τὸ λαῖτμα τῆς καμήλου<br>Χαιρεφῶν ἡ νυκτερίς."}, {"st": "1565", "sp": "Χορός", "t": "τὸ μὲν πόλισμα τῆς Νεφελοκοκκυγίας<br>ὁρᾶν τοδὶ πάρεστιν, οἷ πρεσβεύομεν.<br>οὗτος τί δρᾷς; ἐπ᾽ ἀριστέρ᾽ οὕτως ἀμπέχει;<br>οὐ μεταβαλεῖς θοἰμάτιον ὧδ᾽ ἐπιδέξια;<br>τί ὦ κακόδαιμον; Λαισποδίας εἶ τὴν φύσιν;<br>ὦ δημοκρατία ποῖ προβιβᾷς ἡμᾶς ποτε,<br>εἰ τουτονί γ᾽ ἐχειροτόνησαν οἱ θεοί;"}, {"st": null, "sp": "Τριβαλλός", "t": "ἕξεις ἀτρέμας;"}, {"st": null, "sp": "Ποσειδῶν", "t": "οἴμωζε: πολὺ γὰρ δή σ᾽ ἐγὼ<br>ἑόρακα πάντων βαρβαρώτατον θεῶν.<br>ἄγε δὴ τί δρῶμεν Ἡράκλεις;"}, {"st": null, "sp": "Ἡρακλῆς", "t": "ἀκήκοας<br>ἐμοῦ γ᾽ ὅτι τὸν ἄνθρωπον ἄγχειν βούλομαι,<br>ὅστις ποτ᾽ ἔσθ᾽ ὁ τοὺς θεοὺς ἀποτειχίσας."}, {"st": null, "sp": "Ποσειδῶν", "t": "ἀλλ᾽ ὦγάθ᾽ ᾑρήμεσθα περὶ διαλλαγῶν<br>πρέσβεις."}, {"st": null, "sp": "Ἡρακλῆς", "t": "διπλασίως μᾶλλον ἄγχειν μοι δοκεῖ."}, {"st": null, "sp": "Πισθέταιρος", "t": "τὴν τυρόκνηστίν τις δότω: φέρε σίλφιον:<br>τυρὸν φερέτω τις: πυρπόλει τοὺς ἄνθρακας."}, {"st": null, "sp": "Ποσειδῶν", "t": "τὸν ἄνδρα χαίρειν οἱ θεοὶ κελεύομεν<br>τρεῖς ὄντες ἡμεῖς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ ἐπικνῶ τὸ σίλφιον."}, {"st": null, "sp": "Ἡρακλῆς", "t": "τὰ δὲ κρέα τοῦ ταῦτ᾽ ἐστίν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὄρνιθές τινες<br>ἐπανιστάμενοι τοῖς δημοτικοῖσιν ὀρνέοις<br>ἔδοξαν ἀδικεῖν."}, {"st": null, "sp": "Ἡρακλῆς", "t": "εἶτα δῆτα σίλφιον<br>εἴπικνῇς πρότερον αὐτοῖσιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὦ χαῖρ᾽ Ἡράκλεις.<br>τί ἔστι;"}, {"st": null, "sp": "Ποσειδῶν", "t": "πρεσβεύοντες ἡμεῖς ἥκομεν<br>παρὰ τῶν θεῶν περὶ πολέμου καταλλαγῆς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἔλαιον οὐκ ἔνεστιν ἐν τῇ ληκύθῳ."}, {"st": "1590", "sp": "Ἡρακλῆς", "t": "καὶ μὴν τά γ᾽ ὀρνίθεια λιπάρ᾽ εἶναι πρέπει."}, {"st": null, "sp": "Ποσειδῶν", "t": "ἡμεῖς τε γὰρ πολεμοῦντες οὐ κερδαίνομεν,<br>ὑμεῖς τ᾽ ἂν ἡμῖν τοῖς θεοῖς ὄντες φίλοι<br>ὄμβριον ὕδωρ ἂν εἴχετ᾽ ἐν τοῖς τέλμασιν,<br>ἀλκυονίδας τ᾽ ἂν ἤγεθ᾽ ἡμέρας ἀεί.<br>τούτων περὶ πάντων αὐτοκράτορες ἥκομεν."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλ᾽ οὔτε πρότερον πώποθ᾽ ἡμεῖς ἤρξαμεν<br>πολέμου πρὸς ὑμᾶς, νῦν τ᾽ ἐθέλομεν, εἰ δοκεῖ,<br>ἐάν τι δίκαιον ἀλλὰ νῦν ἐθέλητε δρᾶν,<br>σπονδὰς ποιεῖσθαι. τὰ δὲ δίκαι᾽ ἐστὶν ταδί,<br>τὸ σκῆπτρον ἡμῖν τοῖσιν ὄρνισιν πάλιν<br>τὸν Δί᾽ ἀποδοῦναι: κἂν διαλλαττώμεθα<br>ἐπὶ τοῖσδε, τοὺς πρέσβεις ἐπ᾽ ἄριστον καλῶ."}, {"st": null, "sp": "Ἡρακλῆς", "t": "ἐμοὶ μὲν ἀπόχρη ταῦτα καὶ ψηφίζομαι."}, {"st": null, "sp": "Ποσειδῶν", "t": "τί ὦ κακόδαιμον; ἠλίθιος καὶ γάστρις εἶ.<br>ἀποστερεῖς τὸν πατέρα τῆς τυραννίδος;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ἄληθες; οὐ γὰρ μεῖζον ὑμεῖς οἱ θεοὶ<br>ἰσχύσετ᾽, ἢν ὄρνιθες ἄρξωσιν κάτω;<br>νῦν μέν γ᾽ ὑπὸ ταῖς νεφέλαισιν ἐγκεκρυμμένοι<br>κύψαντες ἐπιορκοῦσιν ὑμᾶς οἱ βροτοί:<br>ἐὰν δὲ τοὺς ὄρνις ἔχητε συμμάχους,<br>ὅταν ὀμνύῃ τις τὸν κόρακα καὶ τὸν Δία,<br>ὁ κόραξ παρελθὼν τοὐπιορκοῦντος λάθρᾳ<br>προσπτόμενος ἐκκόψει τὸν ὀφθαλμὸν θενών."}, {"st": null, "sp": "Ποσειδῶν", "t": "νὴ τὸν Ποσειδῶ ταῦτά γέ τοι καλῶς λέγεις."}, {"st": "1615", "sp": "Ἡρακλῆς", "t": "κἀμοὶ δοκεῖ."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δαὶ σὺ φῄς;"}, {"st": null, "sp": "Τριβαλλός", "t": "ναβαισατρεῦ."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁρᾷς; ἐπαινεῖ χοὖτος. ἕτερόν νυν ἔτι<br>ἀκούσαθ᾽ ὅσον ὑμᾶς ἀγαθὸν ποιήσομεν.<br>ἐάν τις ἀνθρώπων ἱερεῖόν τῳ θεῶν<br>εὐξάμενος εἶτα διασοφίζηται λέγων,<br>‘μενετοὶ θεοί,’ καὶ μἀποδιδῷ μισητίᾳ,<br>ἀναπράξομεν καὶ ταῦτα."}, {"st": null, "sp": "Ποσειδῶν", "t": "φέρ᾽ ἴδω τῷ τρόπῳ;"}, {"st": null, "sp": "N", "t": "ὅταν διαριθμῶν ἀργυρίδιον τύχῃ ἅνθρωπος οὗτος, ἢ καθῆται λούμενος,<br>καταπτόμενος ἰκτῖνος ἁρπάσας λάθρᾳ<br>προβάτοιν δυοῖν τιμὴν ἀνοίσει τῷ θεῷ."}, {"st": null, "sp": "Ἡρακλῆς", "t": "τὸ σκῆπτρον ἀποδοῦναι πάλιν ψηφίζομαι<br>τούτοις ἐγώ."}, {"st": null, "sp": "Ποσειδῶν", "t": "καὶ τὸν Τριβαλλόν νυν ἐροῦ."}, {"st": null, "sp": "Ἡρακλῆς", "t": "ὁ Τριβαλλός, οἰμώζειν δοκεῖ σοι;"}, {"st": null, "sp": "Τριβαλλός", "t": "σαυνάκα<br>βακταρικροῦσα."}, {"st": null, "sp": "Ἡρακλῆς", "t": "φησί μ᾽ εὖ λέγειν πάνυ."}, {"st": "1630", "sp": "Ποσειδῶν", "t": "εἴ τοι δοκεῖ σφῷν ταῦτα, κἀμοὶ συνδοκεῖ."}, {"st": null, "sp": "Ἡρακλῆς", "t": "οὗτος, δοκεῖ δρᾶν ταῦτα τοῦ σκήπτρου πέρι."}, {"st": null, "sp": "Πισθέταιρος", "t": "καὶ νὴ Δί᾽ ἕτερόν γ᾽ ἐστὶν οὗ ‘μνήσθην ἐγώ.<br>τὴν μὲν γὰρ Ἥραν παραδίδωμι τῷ Διί,<br>τὴν δὲ Βασίλειαν τὴν κόρην γυναῖκ᾽ ἐμοὶ<br>ἐκδοτέον ἐστίν."}, {"st": null, "sp": "Ποσειδῶν", "t": "οὐ διαλλαγῶν ἐρᾷς.<br>ἀπίωμεν οἴκαδ᾽ αὖθις."}, {"st": null, "sp": "Πισθέταιρος", "t": "ὀλίγον μοι μέλει.<br>μάγειρε τὸ κατάχυσμα χρὴ ποιεῖν γλυκύ."}, {"st": null, "sp": "Ἡρακλῆς", "t": "ὦ δαιμόνι᾽ ἀνθρώπων Πόσειδον ποῖ φέρει;<br>ἡμεῖς περὶ γυναικὸς μιᾶς πολεμήσομεν;"}, {"st": "1640", "sp": "Ποσειδῶν", "t": "τί δαὶ ποιῶμεν;"}, {"st": null, "sp": "Ἡρακλῆς", "t": "ὅ τι; διαλλαττώμεθα."}, {"st": null, "sp": "Ποσειδῶν", "t": "τί δ᾽ ᾠζύρ᾽; οὐκ οἶσθ᾽ ἐξαπατώμενος πάλαι;<br>βλάπτεις δέ τοι σὺ σαυτόν. ἢν γὰρ ἀποθάνῃ<br>ὁ Ζεὺς παραδοὺς τούτοισι τὴν τυραννίδα,<br>πένης ἔσει σύ. σοῦ γὰρ ἅπαντα γίγνεται<br>τὰ χρήμαθ᾽, ὅσ᾽ ἂν ὁ Ζεὺς ἀποθνῄσκων καταλίπῃ."}, {"st": null, "sp": "Πισθέταιρος", "t": "οἴμοι τάλας οἷόν σε περισοφίζεται.<br>δεῦρ᾽ ὡς ἔμ᾽ ἀποχώρησον, ἵνα τί σοι φράσω.<br>διαβάλλεταί σ᾽ ὁ θεῖος ὦ πόνηρε σύ.<br>τῶν γὰρ πατρῴων οὐδ᾽ ἀκαρῆ μέτεστί σοι<br>κατὰ τοὺς νόμους: νόθος γὰρ εἶ κοὐ γνήσιος."}, {"st": null, "sp": "Ἡρακλῆς", "t": "ἐγὼ νόθος; τί λέγεις;"}, {"st": null, "sp": "Πισθέταιρος", "t": "σὺ μέντοι νὴ Δία<br>ὤν γε ξένης γυναικός. ἢ πῶς ἄν ποτε<br>ἐπίκληρον εἶναι τὴν Ἀθηναίαν δοκεῖς,<br>οὖσαν θυγατέρ᾽, ὄντων ἀδελφῶν γνησίων;"}, {"st": "1655", "sp": "Ἡρακλῆς", "t": "τί δ᾽ ἢν ὁ πατὴρ ἐμοὶ διδῷ τὰ χρήματα<br>νοθεἶ ἀποθνῄσκων;"}, {"st": null, "sp": "Πισθέταιρος", "t": "ὁ νόμος αὐτὸν οὐκ ἐᾷ.<br>οὗτος ὁ Ποσειδῶν πρῶτος, ὃς ἐπαίρει σε νῦν,<br>ἀνθέξεταί σου τῶν πατρῴων χρημάτων<br>φάσκων ἀδελφὸς αὐτὸς εἶναι γνήσιος.<br>ἐρῶ δὲ δὴ καὶ τὸν Σόλωνός σοι νόμον:<br>‘νόθῳ δὲ μὴ εἶναι ἀγχιστείαν παίδων ὄντων<br>γνησίων. ἐὰν δὲ παῖδες μὴ ὦσι γνήσιοι, τοῖς<br>ἐγγυτάτω γένους μετεῖναι τῶν χρημάτων.’"}, {"st": null, "sp": "Ἡρακλῆς", "t": "ἐμοὶ δ᾽ ἄρ᾽ οὐδὲν τῶν πατρῴων χρημάτων<br>μέτεστιν;"}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐ μέντοι μὰ Δία. λέξον δέ μοι,<br>ἤδη σ᾽ ὁ πατὴρ εἰσήγαγ᾽ ἐς τοὺς φράτερας;"}, {"st": "1670", "sp": "Ἡρακλῆς", "t": "οὐ δῆτ᾽ ἐμέ γε. καὶ δῆτ᾽ ἐθαύμαζον πάλαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δῆτ᾽ ἄνω κέχηνας αἴκειαν βλέπων;<br>ἀλλ᾽ ἢν μεθ᾽ ἡμῶν ᾖς, καταστήσας σ᾽ ἐγὼ<br>τύραννον ὀρνίθων παρέξω σοι γάλα."}, {"st": null, "sp": "Ἡρακλῆς", "t": "δίκαι᾽ ἔμοιγε καὶ πάλαι δοκεῖς λέγειν<br>περὶ τῆς κόρης, κἄγωγε παραδίδωμί σοι."}, {"st": null, "sp": "Πισθέταιρος", "t": "τί δαὶ σὺ φῄς;"}, {"st": null, "sp": "Ποσειδῶν", "t": "τἀναντία ψηφίζομαι."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐν τῷ Τριβαλλῷ πᾶν τὸ πρᾶγμα. τί σὺ λέγεις;"}, {"st": null, "sp": "Τριβαλλός", "t": "καλάνι κόραυνα καὶ μεγάλα βασιλιναῦ<br>ὄρνιτο παραδίδωμι."}, {"st": null, "sp": "Ἡρακλῆς", "t": "παραδοῦναι λέγει."}, {"st": "1680", "sp": "Ποσειδῶν", "t": "μὰ τὸν Δί᾽ οὐχ οὗτός γε παραδοῦναι λέγει,<br>εἰ μὴ † βαδίζειν † ωἅσπερ αἱ χελιδόσιν λέγει."}, {"st": null, "sp": "Πισθέταιρος", "t": "οὐκοῦν παραδοῦναι ταῖς χελιδόσιν λέγει."}, {"st": null, "sp": "Ποσειδῶν", "t": "σφὼ νῦν διαλλάττεσθε καὶ ξυμβαίνετε:<br>ἐγὼ δ᾽, ἐπειδὴ σφῷν δοκεῖ, σιγήσομαι."}, {"st": "1685", "sp": "Ἡρακλῆς", "t": "ἡμῖν ἃ λέγεις σὺ πάντα συγχωρεῖν δοκεῖ.<br>ἀλλ᾽ ἴθι μεθ᾽ ἡμῶν αὐτὸς ἐς τὸν οὐρανόν,<br>ἵνα τὴν Βασίλειαν καὶ τὰ πάντ᾽ ἐκεῖ λάβῃς."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἐς καιρὸν ἆρα κατεκόπησαν οὑτοιὶ<br>ἐς τοὺς γάμους."}, {"st": null, "sp": "Ἡρακλῆς", "t": "βούλεσθε δῆτ᾽ ἐγὼ τέως<br>ὀπτῶ τὰ κρέα ταυτὶ μένων; ὑμεῖς δ᾽ ἴτε."}, {"st": null, "sp": "Ποσειδῶν", "t": "ὀπτᾷς τὰ κρέα; πολλήν γε τενθείαν λέγεις.<br>οὐκ εἶ μεθ᾽ ἡμῶν;"}, {"st": null, "sp": "Ἡρακλῆς", "t": "εὖ γε μέντἂν διετέθην."}, {"st": null, "sp": "Πισθέταιρος", "t": "ἀλλὰ γαμικὴν χλανίδα δότω τις δεῦρό μοι."}, {"st": null, "sp": "Χορός", "t": "ἔστι δ᾽ ἐν Φαναῖσι πρὸς τῇ<br>Κλεψύδρᾳ πανοῦργον ἐγ-<br>γλωττογαστόρων γένος,<br>οἳ θερίζουσίν τε καὶ σπείρουσι<br>καὶ τρυγῶσι ταῖς γλώτταισι<br>συκάζουσί τε:<br>βάρβαροι δ᾽ εἰσὶν γένος,<br>Γοργίαι τε καὶ Φίλιπποι.<br>κἀπὸ τῶν ἐγγλωττογαστόρων<br>ἐκείνων τῶν Φιλίππων<br>πανταχοῦ τῆς Ἀττικῆς ἡ<br>γλῶττα χωρὶς τέμνεται."}, {"st": null, "sp": "Χορός", "t": "ὦ πάντ᾽ ἀγαθὰ πράττοντες, ὦ μείζω λόγου,<br>ὦ τρισμακάριον πτηνὸν ὀρνίθων γένος,<br>δέχεσθε τὸν τύραννον ὀλβίοις δόμοις.<br>προσέρχεται γὰρ οἷς οὔτε παμφαὴς<br>ἀστὴρ ἰδεῖν ἔλαμψε χρυσαυγεῖ δόμῳ,<br>οὔθ᾽ ἡλίου τηλαυγὲς ἀκτίνων σέλας<br>τοιοῦτον ἐξέλαμψεν, οἶον ἔρχεται<br>ἔχων γυναικὸς κάλλος οὐ φατὸν λέγειν,<br>πάλλων κεραυνόν, πτεροφόρον Διὸς βέλος:<br>ὀσμὴ δ᾽ ἀνωνόμαστος ἐς βάθος κύκλου<br>χωρεῖ, καλὸν θέαμα: θυμιαμάτων δ᾽<br>αὖραι διαψαίρουσι πλεκτάνην καπνοῦ.<br>ὁδὶ δὲ καὐτός ἐστιν. ἀλλὰ χρὴ θεᾶς<br>Μούσης ἀνοίγειν ἱερὸν εὔφημον στόμα."}, {"st": "1720", "sp": "Χορός", "t": "ἄναγε δίεχε πάραγε πάρεχε.<br>περιπέτεσθε<br>τὸν μάκαρα μάκαρι σὺν τύχᾳ.<br>ὦ φεῦ φεῦ τῆς ὥρας τοῦ κάλλους.<br>ὦ μακαριστὸν σὺ γάμον τῇδε πόλει γημας."}, {"st": null, "sp": "N", "t": "μεγάλαι μεγάλαι κατέχουσι τύχαι γένος ὀρνίθων<br>διὰ τόνδε τὸν ἄνδρ᾽. ἀλλ᾽ ὑμεναίοις<br>καὶ νυμφιδίοισι δέχεσθ᾽ ᾠδαῖς<br>αὐτὸν καὶ τὴν Βασίλειαν."}, {"st": null, "sp": "Ἥρᾳ ποτ᾽ Ὀλυμπίᾳ", "t": "Ἥρᾳ ποτ᾽ Ὀλυμπίᾳ<br>τῶν ἠλιβάτων θρόνων<br>ἄρχοντα θεοῖς μέγαν<br>Μοῖραι ξυνεκοίμισαν<br>ἐν τοιῷδ᾽ ὑμεναίῳ.<br>Ὑμὴν ὦ Ὑμέναι᾽ ὦ,<br>Ὑμὴν ὦ Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "N", "t": "ὁ δ᾽ ἀμφιθαλὴς Ἔρως χρυσόπτερος ἡνίας<br>ηὔθυνε παλιντόνους,<br>Ζηνὸς πάροχος γάμων<br>τῆς τ᾽ εὐδαίμονος Ἥρας.<br>Ὑμὴν ὦ Ὑμέναι᾽ ὦ,<br>Ὑμὴν ὦ Ὑμέναι᾽ ὦ."}, {"st": null, "sp": "Χορός", "t": "ἐχάρην ὕμνοις, ἐχάρην ᾠδαῖς:<br>ἄγαμαι δὲ λόγων. ἄγε νυν αὐτοῦ<br>καὶ τὰς χθονίας κλῄσατε βροντὰς<br>τάς τε πυρώδεις Διὸς ἀστεροπὰς<br>δεινόν τ᾽ ἀργῆτα κεραυνόν."}, {"st": null, "sp": "Χορός", "t": "ὦ μέγα χρύσεον ἀστεροπῆς φάος,<br>ὦ Διὸς ἄμβροτον ἔγχος πυρφόρον,<br>ὦ χθόνιαι βαρυαχέες<br>ὀμβροφόροι θ᾽ ἅμα βρονταί,<br>αἷς ὅδε νῦν χθόνα σείει.<br>διὰ σὲ τὰ πάντα κρατήσας<br>καὶ πάρεδρον Βασίλειαν ἔχει Διός.<br>Ὑμὴν ὦ Ὑμέναι᾽ ὦ."}, {"st": "1755", "sp": "Πισθέταιρος", "t": "ἔπεσθε νῦν γάμοισιν ὦ<br>φῦλα πάντα συννόμων<br>πτεροφόρ᾽ ἐπὶ δάπεδον Διὸς<br>καὶ λέχος γαμήλιον.<br>ὄρεξον ὦ μάκαιρα σὴν<br>χεῖρα καὶ πτερῶν ἐμῶν<br>λαβοῦσα συγχόρευσον: αἴρων<br>δὲ κουφιῶ σ᾽ ἐγώ."}, {"st": null, "sp": "Χορός", "t": "ἀλαλαλαὶ ἰὴ παιών,<br>τήνελλα καλλίνικος, ὦ<br>δαιμόνων ὑπέρτατε."}],[]);})();
